-- CommandProject: strategic commander for the skirmish AI (generated by the launcher).
-- Appended to the game's own SkirmishAISystem.lua; SkirmishDelaySetup forks CPCommanderRun for
-- every skirmish AI brain. The game's neural attack platoons live in the engine (C++), so this
-- takes the AI's army, fleet and air force into its own platoons and decides where and when they
-- fight. Everything runs inside pcall; after repeated errors the units go back to the engine, so a
-- problem here never leaves the AI worse than the original.
--
--   snapshot  one picture of every army per ~2.5 s (25-unit grid), shared by all commanders
--   army      gathers at an ambush point (narrow passages, high ground, the route the human
--             uses), attacks only with clear superiority, picks strategic targets, pincer with a
--             diversion, focus fire, artillery on high ground, escorts experimentals, retreats to
--             the nearest towers, sends the wounded home, avoids places where it keeps dying
--   fleet     hunts what its ships can reach
--   air       fighters for air superiority and escort, bombers on weakly defended targets,
--             gunships supporting the army
--   commander the ACU flees when hurt and helps defend early on
--   transports load, fly and drop troops on islands and extractors out of reach by land
--   scouting  scouts the enemy and answers with counter units and research
--   bases     towers where the human strikes, a forward outpost, a protected economic base,
--             repairs after fights
--   team      allied AIs converge on the same target and help an ally under attack
--   adaptive  more pressure when the human is winning easily, more caution when losing badly
--   player    a model of the human (style, timing, routes, favourite targets and expansions),
--             remembered between matches through the interface (Game.prefs)
--   status    with one human in the match, the plan of every AI goes to the in-game panel
do
local CFG = {
    level = @LEVEL@,
    raids = @RAIDS@,
    personality = '@PERSONALITY@',
    air = @AIR@,
    micro = @MICRO@,
    build = @BUILD@,
    counter = @COUNTER@,
    team = @TEAM@,
    adaptive = @ADAPTIVE@,
    status = @STATUS@,
    learn = @LEARN@,
    aggression = @AGGRESSION@,
    districts = @DISTRICTS@,
    airbias = @AIRBIAS@,
    navalbias = @NAVALBIAS@,
    tips = @TIPS@,
    chat = @CHAT@,
}
local CP_DEBUG = false

-- personalities: patience (ratio), army size, raids, defenses, pincer and air emphasis
local PERSONALITIES = {
    balanced = { label = 'Equilibrada', ratio = 1.35, size = 1.0, raid = 5, towers = 1.0, pincer = true, air = 1.0 },
    aggressive = { label = 'Agressiva', ratio = 1.15, size = 0.75, raid = 5, towers = 0.6, pincer = true, air = 1.2 },
    defensive = { label = 'Defensiva', ratio = 1.6, size = 1.4, raid = 2, towers = 1.8, pincer = false, air = 0.8 },
    raider = { label = 'Saqueadora', ratio = 1.35, size = 1.0, raid = 10, towers = 0.8, pincer = true, air = 1.0 },
    naval = { label = 'Naval', ratio = 1.3, size = 1.0, raid = 4, towers = 1.0, pincer = true, air = 0.8, fleet = 0.6 },
    airborne = { label = 'Aerea', ratio = 1.3, size = 1.1, raid = 4, towers = 1.0, pincer = false, air = 1.6 },
    engineer = { label = 'Engenheira', ratio = 1.5, size = 1.2, raid = 3, towers = 2.0, pincer = false, air = 1.0, expand = 1.4 },
    blitz = { label = 'Relampago', ratio = 1.05, size = 0.6, raid = 8, towers = 0.5, pincer = true, air = 1.0 },
    titan = { label = 'Experimental', ratio = 1.45, size = 1.2, raid = 2, towers = 1.2, pincer = false, air = 1.0, tech = 1.6 },
}
local PERSONALITY_ORDER = { 'balanced', 'aggressive', 'defensive', 'raider', 'naval', 'airborne', 'engineer', 'blitz', 'titan' }

-- unit ids per faction (1 UEF, 2 Cybran, 3 Illuminate) for counters and buildings
local UNITS = {
    { aaLand = 'uul0105', fighter = 'uua0101', bomber = 'uua0102', arty = 'uul0102', tank = 'uul0101', ship = 'uus0102',
      factory = 'uub0001', tower = 'uub0101', aatower = 'uub0102', shield = 'uub0202',
      airfactory = 'uub0002', energy = 'uub0702', research = 'uub0801', artillery = 'uub0105', radar = 'uub0301', engineer = 'uul0002',
      navalfactory = 'uub0003', expfactory = 'uub0011', transport = 'uua0901' },
    { aaLand = false, fighter = 'uca0104', bomber = 'uca0104', arty = 'ucl0102', tank = 'ucl0103', ship = 'ucs0103',
      factory = 'ucb0001', tower = 'ucb0101', aatower = 'ucb0102', shield = 'ucb0202',
      airfactory = 'ucb0002', energy = 'ucb0702', research = 'ucb0801', artillery = 'ucb0105', radar = 'ucb0303', engineer = 'ucl0002',
      navalfactory = 'ucb0003', expfactory = 'ucb0011', transport = false },
    { aaLand = 'uil0105', fighter = 'uia0104', bomber = 'uia0104', arty = 'uil0104', tank = 'uil0101', ship = false,
      factory = 'uib0001', tower = 'uib0101', aatower = 'uib0102', shield = 'uib0202',
      airfactory = 'uib0002', energy = 'uib0702', research = 'uib0801', artillery = false, radar = 'uib0301', engineer = 'uil0002',
      navalfactory = false, expfactory = 'uib0011', transport = false },
}

-- shared by every AI commander in the match (allies coordinate through it)
CPAI = CPAI or { commanders = {} }
CPAI.status = CPAI.status or {} -- army -> what the in-game panel shows

-- ---------------------------------------------------------------- helpers
local CAT = false
local function Cat(expr)
    local ok, c = pcall(ParseEntityCategory, expr)
    if ok then return c end
    return false
end
local function Categories()
    if CAT then return CAT end
    CAT = {
        army = Cat('MOBILE LAND -ENGINEER -COMMAND -TRANSPORTATION'),
        fleet = Cat('MOBILE NAVAL -ENGINEER'),
        air = Cat('MOBILE AIR -ENGINEER -TRANSPORTATION'),
        transport = Cat('MOBILE AIR TRANSPORTATION'),
        engineer = Cat('MOBILE ENGINEER -COMMAND'),
        acu = Cat('COMMAND'),
        mobile = Cat('MOBILE'),
        enemyAir = Cat('AIR'),
        naval = Cat('NAVAL'),
        structure = Cat('STRUCTURE'),
        extractor = Cat('MASSEXTRACTION'),
        factory = Cat('FACTORY'),
        experimental = Cat('EXPERIMENTAL'),
        indirect = Cat('INDIRECTFIRE'),
        fighter = Cat('FIGHTER'),
        bomber = Cat('BOMBER'),
        gunship = Cat('GROUNDATTACK'),
        antiair = Cat('ANTIAIR'),
        artillery = Cat('ARTILLERY'),
        engineerAny = Cat('ENGINEER'),
        nuke = Cat('NUKE STRUCTURE'),
        shield = Cat('SHIELD STRUCTURE'),
        expfactory = Cat('EXPERIMENTALFACTORY'),
        radar = Cat('RADAR STRUCTURE'),
    }
    return CAT
end

local function Is(cat, u)
    if not cat then return false end
    local ok, yes = pcall(EntityCategoryContains, cat, u)
    return ok and yes
end

local function Now()
    local ok, t = pcall(GetGameTimeSeconds)
    if ok and t then return t end
    return 0
end

local function Dist(a, b)
    return VDist2(a[1], a[3], b[1], b[3])
end

local function Point(x, z)
    local ok, y = pcall(GetSurfaceHeight, x, z)
    return { x, ok and y or 0, z }
end

local function Toward(from, to, distance)
    local d = Dist(from, to)
    if d <= 0 then return from end
    local k = distance / d
    return Point(from[1] + (to[1] - from[1]) * k, from[3] + (to[3] - from[3]) * k)
end

local function Alive(u)
    if not u then return false end
    local ok, dead = pcall(u.IsDead, u)
    return ok and not dead
end

local function Ready(u)
    if not Alive(u) then return false end
    local ok, building = pcall(u.IsBeingBuilt, u)
    if ok and building then return false end
    local ok2, attached = pcall(u.IsUnitState, u, 'Attached')
    return not (ok2 and attached)
end

local function HealthFraction(u)
    local ok, h = pcall(u.GetHealth, u)
    local ok2, m = pcall(u.GetMaxHealth, u)
    if ok and ok2 and h and m and m > 0 then return h / m end
    return 1
end

local function Defense(u)
    local ok, bp = pcall(u.GetBlueprint, u)
    if ok and bp and bp.Defense then return bp.Defense end
    return {}
end

-- combat strength against ground targets (threat from the blueprint, scaled by health)
local function Power(u, structuresCount)
    local d = Defense(u)
    local p = (d.SurfaceThreatLevel or 0) + (d.SubThreatLevel or 0) * 0.5
    if p <= 0 and not structuresCount then
        -- units without a threat rating still count by how tough they are
        local ok, m = pcall(u.GetMaxHealth, u)
        p = ok and m and m / 300 or 0
    end
    return p * (0.35 + 0.65 * HealthFraction(u))
end

-- strength against aircraft
local function AirPower(u)
    return (Defense(u).AirThreatLevel or 0) * (0.35 + 0.65 * HealthFraction(u))
end

local function Speed(u)
    local ok, bp = pcall(u.GetBlueprint, u)
    if ok and bp and bp.Physics then return bp.Physics.MaxSpeed or 0 end
    return 0
end

-- centre of the main body of a group (stragglers far from the first estimate are ignored)
local function Centroid(units)
    local x, z, n = 0, 0, 0
    for _, u in ipairs(units) do
        local p = u:GetPosition()
        x, z, n = x + p[1], z + p[3], n + 1
    end
    if n == 0 then return false end
    local c = { x / n, 0, z / n }
    local x2, z2, n2 = 0, 0, 0
    for _, u in ipairs(units) do
        local p = u:GetPosition()
        if VDist2(p[1], p[3], c[1], c[3]) < 80 then x2, z2, n2 = x2 + p[1], z2 + p[3], n2 + 1 end
    end
    if n2 * 2 >= n then return Point(x2 / n2, z2 / n2) end
    return Point(c[1], c[3])
end

local function Spread(units, center)
    local m = 0
    for _, u in ipairs(units) do
        local d = Dist(u:GetPosition(), center)
        if d > m then m = d end
    end
    return m
end

local function Around(brain, cat, pos, radius, who)
    if not cat then return {} end
    local ok, list = pcall(brain.GetUnitsAroundPoint, brain, cat, pos, radius, who)
    if ok and list then return list end
    return {}
end

local function ListOf(brain, cat)
    if not cat then return {} end
    local ok, list = pcall(brain.GetListOfUnits, brain, cat, false)
    if ok and list then return list end
    return {}
end

local function PowerOf(units)
    local t = 0
    for _, u in ipairs(units) do t = t + Power(u) end
    return t
end

local function AirPowerOf(units)
    local t = 0
    for _, u in ipairs(units) do t = t + AirPower(u) end
    return t
end

local function Order(units, kind, pos, queue)
    if table.getn(units) == 0 or not pos then return end
    if not queue then pcall(IssueClearCommands, units) end
    if kind == 'attack' then
        pcall(IssueAggressiveMove, units, pos)
    else
        pcall(IssueMove, units, pos)
    end
end

local function Stored(brain, kind)
    local ok, v = pcall(brain.GetEconomyStored, brain, kind)
    if ok and v then return v end
    return 0
end

local function Log(brain, text)
    if CP_DEBUG then LOG('*CP AI ' .. brain:GetArmyIndex() .. ': ' .. text) end
end

local function Allied(a, b)
    if a == b then return false end
    local ok, yes = pcall(IsAlly, a, b)
    if ok then return yes and true or false end
    local ok2, enemy = pcall(IsEnemy, a, b)
    return ok2 and not enemy
end

local function Enemy(a, b)
    if a == b then return false end
    local ok, yes = pcall(IsEnemy, a, b)
    return ok and yes
end

local function Defeated(b)
    local ok, d = pcall(b.IsDefeated, b)
    return ok and d
end

local function Civilian(index)
    local ok, civ = pcall(ArmyIsCivilian, index)
    return ok and civ
end

-- humans still playing
local function Humans()
    local n = 0
    for _, b in ArmyBrains do
        local ok, idx = pcall(b.GetArmyIndex, b)
        if ok and b.BrainType == 'Human' and not Civilian(idx) and not Defeated(b) then n = n + 1 end
    end
    return n
end

local function Rand(a, b)
    local ok, v = pcall(Random, a, b)
    if ok and type(v) == 'number' then return math.max(a, math.min(b, math.floor(v))) end
    return a
end

-- ---------------------------------------------------------------- snapshot of every army
-- One pass over all units every ~2.5 s, shared by every commander: ground strength, anti-air and
-- towers per 25-unit cell, structures and mobile units per army. Danger checks become sums over
-- a few cells instead of hundreds of area queries.
local SNAP_CELL = 25

local function SnapKey(x, z)
    return math.floor(x / SNAP_CELL) .. ':' .. math.floor(z / SNAP_CELL)
end

-- players in the match (without civilians): big matches (more than 8) look at the map less often
local function ArmyCount()
    if CPAI.armyCount then return CPAI.armyCount end
    local n = 0
    for _, b in ArmyBrains do
        local ok, idx = pcall(b.GetArmyIndex, b)
        if ok and not Civilian(idx) then n = n + 1 end
    end
    CPAI.armyCount = math.max(1, n)
    return CPAI.armyCount
end

local function Snapshot()
    local t = Now()
    local S = CPAI.snap
    if S and t - S.t < 2.5 * math.max(1, ArmyCount() / 8) then return S end
    local c = Categories()
    S = { t = t, armies = {} }
    for _, b in ArmyBrains do
        local ok, idx = pcall(b.GetArmyIndex, b)
        if ok and not Defeated(b) then
            local A = { brain = b, index = idx, human = b.BrainType == 'Human', ground = {}, towers = {}, aa = {},
                structs = {}, mobile = {}, air = {}, power = 0, airPower = 0, extractors = 0 }
            for _, u in ipairs(ListOf(b, c.mobile)) do
                if Ready(u) then
                    local pos = u:GetPosition()
                    local key = SnapKey(pos[1], pos[3])
                    local isAir = Is(c.enemyAir, u)
                    local engineer = Is(c.engineerAny, u) and not Is(c.acu, u)
                    local p = engineer and 0 or Power(u)
                    local ap = AirPower(u)
                    local info = { u = u, pos = pos, p = p, ap = ap, air = isAir,
                        naval = Is(c.naval, u), exp = Is(c.experimental, u), indirect = Is(c.indirect, u), engineer = engineer }
                    if isAir then
                        table.insert(A.air, info)
                    else
                        A.ground[key] = (A.ground[key] or 0) + p
                    end
                    if ap > 0 then A.aa[key] = (A.aa[key] or 0) + ap end
                    table.insert(A.mobile, info)
                    A.power = A.power + p
                    A.airPower = A.airPower + ap
                end
            end
            for _, u in ipairs(ListOf(b, c.structure)) do
                if Ready(u) then
                    local pos = u:GetPosition()
                    local key = SnapKey(pos[1], pos[3])
                    local p = Power(u, true)
                    local ap = AirPower(u)
                    if p > 0 then A.towers[key] = (A.towers[key] or 0) + p end
                    if ap > 0 then A.aa[key] = (A.aa[key] or 0) + ap end
                    local kind = 'other'
                    if Is(c.extractor, u) then
                        kind = 'extractor'
                        A.extractors = A.extractors + 1
                    elseif Is(c.expfactory, u) then
                        kind = 'expfactory'
                    elseif Is(c.factory, u) then
                        kind = 'factory'
                    elseif Is(c.artillery, u) or Is(c.indirect, u) then
                        kind = 'artillery'
                    elseif Is(c.shield, u) then
                        kind = 'shield'
                    elseif Is(c.radar, u) then
                        kind = 'radar'
                    end
                    table.insert(A.structs, { u = u, pos = pos, kind = kind, defense = p + ap, aa = ap, nuke = Is(c.nuke, u) })
                end
            end
            S.armies[idx] = A
        end
    end
    CPAI.snap = S
    return S
end

-- sum of a per-cell layer of the given armies around a point
local function SumAround(S, armies, layer, pos, radius)
    local total = 0
    local x0, x1 = math.floor((pos[1] - radius) / SNAP_CELL), math.floor((pos[1] + radius) / SNAP_CELL)
    local z0, z1 = math.floor((pos[3] - radius) / SNAP_CELL), math.floor((pos[3] + radius) / SNAP_CELL)
    local reach = radius + SNAP_CELL * 0.5
    for _, idx in ipairs(armies) do
        local A = S.armies[idx]
        local grid = A and A[layer]
        if grid then
            for cx = x0, x1 do
                for cz = z0, z1 do
                    local v = grid[cx .. ':' .. cz]
                    if v and VDist2((cx + 0.5) * SNAP_CELL, (cz + 0.5) * SNAP_CELL, pos[1], pos[3]) <= reach then
                        total = total + v
                    end
                end
            end
        end
    end
    return total
end

-- armies (indexes) that are enemies of `army` and still in the snapshot
local function EnemyArmies(S, army)
    local list = {}
    for idx, A in S.armies do
        if Enemy(army, idx) and not Civilian(idx) then table.insert(list, idx) end
    end
    return list
end

-- ---------------------------------------------------------------- terrain and map markers
-- Ambushes go to narrow passages and high ground near the planned spot (and to the map's own
-- "Defensive Point" markers); artillery looks for high ground behind the front.
local GRID = 50

local function CellKey(p)
    return math.floor(p[1] / GRID) .. ':' .. math.floor(p[3] / GRID)
end

local function CellCenter(key)
    local i = string.find(key, ':', 1, true)
    if not i then return Point(0, 0) end
    local a = tonumber(string.sub(key, 1, i - 1)) or 0
    local b = tonumber(string.sub(key, i + 1)) or 0
    return Point(a * GRID + GRID / 2, b * GRID + GRID / 2)
end

local function Height(x, z)
    local ok, h = pcall(GetTerrainHeight, x, z)
    if ok and h then return h end
    return 0
end

local function IsWater(x, z)
    local ok, s = pcall(GetSurfaceHeight, x, z)
    return ok and s and s > Height(x, z) + 0.5
end

-- passable width across the direction (dx, dz): walks sideways until a cliff or water (max 120)
local function Corridor(p, dx, dz)
    local px, pz = -dz, dx
    local width = 0
    for side = -1, 1, 2 do
        local lastH = Height(p[1], p[3])
        for step = 1, 12 do
            local x = p[1] + px * side * step * 5
            local z = p[3] + pz * side * step * 5
            local h = Height(x, z)
            if IsWater(x, z) or math.abs(h - lastH) > 3 then break end
            width = width + 5
            lastH = h
        end
    end
    return width
end

-- how much a point stands above the ground around it (radius 20)
local function HighGround(p)
    local h = Height(p[1], p[3])
    local sum = 0
    for i = 0, 7 do
        local a = i * 0.785
        sum = sum + Height(p[1] + math.cos(a) * 20, p[3] + math.sin(a) * 20)
    end
    return h - sum / 8
end

local MARKERS = false
local function Markers()
    if MARKERS then return MARKERS end
    MARKERS = { defensive = {}, expansion = {} }
    pcall(function()
        local SU = import('/lua/sim/ScenarioUtilities.lua')
        for _, m in (SU.GetMarkersByType('Defensive Point') or {}) do
            if m.position then table.insert(MARKERS.defensive, m.position) end
        end
        for _, m in (SU.GetMarkersByType('Expansion Area') or {}) do
            if m.position then table.insert(MARKERS.expansion, m.position) end
        end
    end)
    return MARKERS
end

-- the best place to wait near `spot`, facing `enemy`: narrow, high, away from where we died
local function AmbushSpot(spot, enemy, kills)
    local d = Dist(spot, enemy)
    if d <= 0 then return spot end
    local dx, dz = (enemy[1] - spot[1]) / d, (enemy[3] - spot[3]) / d
    local candidates = { spot }
    for ring = 1, 2 do
        for i = 0, 7 do
            local a = i * 0.785
            table.insert(candidates, Point(spot[1] + math.cos(a) * 25 * ring, spot[3] + math.sin(a) * 25 * ring))
        end
    end
    for _, m in Markers().defensive do
        if Dist(m, spot) < 100 then table.insert(candidates, Point(m[1], m[3])) end
    end
    local best, bestScore = spot, -1000
    for _, c in candidates do
        if not IsWater(c[1], c[3]) then
            local choke = (120 - Corridor(c, dx, dz)) / 120
            local high = HighGround(c) / 10
            if high > 1 then high = 1 end
            if high < -1 then high = -1 end
            local score = choke * 1.2 + high * 0.8 - Dist(c, spot) / 100 - (kills[CellKey(c)] or 0) * 0.3
            if score > bestScore then best, bestScore = c, score end
        end
    end
    return best
end

-- the highest point near `behind` (for artillery)
local function HighSpot(behind)
    local best, bestH = behind, HighGround(behind)
    for i = 0, 5 do
        local a = i * 1.047
        local c = Point(behind[1] + math.cos(a) * 12, behind[3] + math.sin(a) * 12)
        local h = HighGround(c)
        if h > bestH and not IsWater(c[1], c[3]) then best, bestH = c, h end
    end
    return best
end

-- ---------------------------------------------------------------- the player model
-- One model for the whole match: what the human builds, when and where they attack, which of our
-- places they hit, where they expand and which style they play. Only AIs that are enemies of the
-- human use it. With a single human, the interface keeps it in Game.prefs and sends it back next
-- match (CPAIReceiveMemory), so the AI starts every game already prepared for this player.
local STYLE_KEYS = { 'rush', 'turtle', 'air', 'naval', 'raider', 'eco', 'tech' }
local STYLE_LABEL = {
    rush = 'rush (ataca cedo)', turtle = 'defensivo (muitas torres)', air = 'aereo', naval = 'naval',
    raider = 'saqueador (ataques pequenos em extratores)', eco = 'economico (muitas expansoes)',
    tech = 'experimentais', balanced = 'equilibrado',
}

local function Clamp(v)
    if v < 0 then return 0 end
    if v > 1 then return 1 end
    return v
end

local function Top(map, n)
    local list = {}
    for k, w in map do table.insert(list, { k = k, w = w }) end
    table.sort(list, function(a, b) return a.w > b.w end)
    local out = {}
    for i = 1, math.min(n, table.getn(list)) do out[list[i].k] = math.floor(list[i].w * 100 + 0.5) / 100 end
    return out
end

local function NewModel()
    local style, raw = {}, {}
    for _, k in ipairs(STYLE_KEYS) do
        style[k] = 0
        raw[k] = 0
    end
    return {
        style = style, raw = raw, prior = false,
        shares = { land = 0, air = 0, naval = 0, arty = 0, exp = 0, defense = 0 },
        route = {}, hit = {}, expand = {}, held = {}, lost = {},
        firstAttack = false, expectedAttack = false, attacks = 0, raids = 0, lastAttackAt = -999,
        extractors = 0, experimentals = 0, expPos = false, expPower = 0,
        dominant = 'balanced', games = 0, humans = 0, nukes = false,
    }
end

local function Model()
    if not CPAI.model then CPAI.model = NewModel() end
    return CPAI.model
end

-- what the previous matches taught (sent by the interface at the start of the match)
function CPAIReceiveMemory(data)
    if type(data) ~= 'table' then return end
    local M = Model()
    local prior = {}
    for _, k in ipairs(STYLE_KEYS) do
        local v = type(data.style) == 'table' and data.style[k]
        prior[k] = type(v) == 'number' and Clamp(v) or 0
    end
    M.prior = prior
    for _, k in ipairs(STYLE_KEYS) do M.style[k] = math.max(M.style[k] or 0, prior[k]) end
    M.games = type(data.games) == 'number' and data.games or 0
    -- the Alsyper genes learned so far (this map first, then in general) and the record against
    -- the player: each human win makes the next AI a little stronger
    if type(data.genes) == 'table' then CPAI.genesPrior = data.genes end
    CPAI.generation = M.games
    if type(data.results) == 'table' then
        local sum = 0
        for _, r in ipairs(data.results) do if type(r) == 'number' then sum = sum + r end end
        CPAI.strength = math.max(0.7, math.min(1.5, 1 + sum * 0.06))
    end
    for _, cmd in CPAI.commanders do
        if cmd.genes and Now() < 60 then cmd.genes = nil end
    end
    if type(data.firstAttack) == 'number' and data.firstAttack > 0 then M.expectedAttack = data.firstAttack end
    for _, name in { 'route', 'hit', 'expand', 'held', 'lost' } do
        M[name] = M[name] or {}
        local src = data[name]
        if type(src) == 'table' then
            local count = 0
            for key, w in src do
                count = count + 1
                if count > 24 then break end
                if type(key) == 'string' and type(w) == 'number' and string.find(key, '^%-?%d+:%-?%d+$') then
                    M[name][key] = math.max(M[name][key] or 0, math.min(w, 50) * 0.6)
                end
            end
        end
    end
end

-- the player pressed "forget" in the panel: start from scratch
function CPAIForgetModel()
    local humans = CPAI.model and CPAI.model.humans or 0
    CPAI.model = NewModel()
    CPAI.model.humans = humans
    CPAI.rememberedAt = Now()
end

-- humans that are enemies of at least one AI commander
local function HumanEnemies(S)
    local list = {}
    for idx, A in S.armies do
        if A.human and not Civilian(idx) then
            for army, _ in CPAI.commanders do
                if Enemy(army, idx) then
                    table.insert(list, A)
                    break
                end
            end
        end
    end
    return list
end

function CPAIModelUpdate()
    local M = Model()
    local S = Snapshot()
    local t = Now()
    local humans = HumanEnemies(S)
    M.humans = table.getn(humans)
    if M.humans == 0 then return end

    -- memories fade: recent behaviour counts more
    for _, name in { 'route', 'hit', 'expand' } do
        local map = M[name]
        for k, w in map do
            w = w * 0.97
            if w < 0.05 then map[k] = nil else map[k] = w end
        end
    end

    local shares = { land = 0, air = 0, naval = 0, arty = 0, exp = 0, defense = 0 }
    local extractors, exps, expPos, expPower, nukes = 0, 0, false, 0, false
    local cells = {}
    for _, A in ipairs(humans) do
        for _, m in ipairs(A.mobile) do
            if not m.engineer then
                local p = m.p + m.ap * 0.5
                if m.exp then
                    shares.exp = shares.exp + p
                    exps = exps + 1
                    if p > expPower then expPos, expPower = m.pos, p end
                elseif m.air then
                    shares.air = shares.air + p
                elseif m.naval then
                    shares.naval = shares.naval + p
                elseif m.indirect then
                    shares.arty = shares.arty + p
                else
                    shares.land = shares.land + p
                end
                if not m.air then
                    local key = CellKey(m.pos)
                    local cell = cells[key]
                    if not cell then
                        cell = { pos = m.pos, power = 0, n = 0, army = A.index }
                        cells[key] = cell
                    end
                    cell.power = cell.power + p
                    cell.n = cell.n + 1
                end
            end
        end
        for _, s in ipairs(A.structs) do
            if s.defense > 0 then shares.defense = shares.defense + s.defense end
            if s.nuke then nukes = true end
            if s.kind == 'extractor' or s.kind == 'factory' then
                local key = CellKey(s.pos)
                M.expand[key] = math.min(20, (M.expand[key] or 0) + 0.3)
                if s.kind == 'extractor' then extractors = extractors + 1 end
            end
        end
    end
    local total = 0
    for _, v in shares do total = total + v end
    if total > 0 then
        for k, v in shares do M.shares[k] = M.shares[k] * 0.7 + (v / total) * 0.3 end
    end
    M.extractors, M.experimentals, M.expPos, M.expPower, M.nukes = extractors, exps, expPos, expPower, nukes

    -- where the human armies walk, and which places of the AIs that fight them they come for
    for key, cell in cells do
        if cell.power >= 4 then
            M.route[key] = math.min(50, (M.route[key] or 0) + cell.power * 0.05)
            local near = false
            for army, cmd in CPAI.commanders do
                if Enemy(army, cell.army) then
                    for _, cl in (cmd.lastClusters or {}) do
                        if Dist(cl.pos, cell.pos) < 70 then
                            near = cl
                            break
                        end
                    end
                end
                if near then break end
            end
            if near then
                local hk = CellKey(near.pos)
                M.hit[hk] = math.min(50, (M.hit[hk] or 0) + cell.power * 0.1)
                if t - M.lastAttackAt > 45 then
                    if cell.n < 6 and (near.factories or 0) == 0 then
                        M.raids = M.raids + 1
                    else
                        M.attacks = M.attacks + 1
                    end
                    M.firstAttack = M.firstAttack or t
                end
                M.lastAttackAt = t
            end
        end
    end

    -- style scores (0..1): `raw` is this match only (what goes to memory); `style` also uses
    -- what earlier matches taught (what the AI acts on)
    local aiExtractors, n = 0, 0
    for _, cmd in CPAI.commanders do
        aiExtractors = aiExtractors + (cmd.extractors or 0)
        n = n + 1
    end
    if n > 0 then aiExtractors = aiExtractors / n end
    local first = M.firstAttack
    local raw = {
        rush = first and ((first < 300 and 1) or (first < 480 and 0.6) or 0.15) or 0,
        turtle = Clamp((M.shares.defense - 0.15) * 3) * ((M.attacks + M.raids) < 2 and 1 or 0.5),
        air = Clamp((M.shares.air - 0.15) * 2.5),
        naval = Clamp((M.shares.naval - 0.1) * 3),
        raider = M.raids >= 2 and Clamp(M.raids / (M.raids + M.attacks) * 1.2) or 0,
        eco = Clamp((extractors - aiExtractors) / 6),
        tech = exps > 0 and ((t < 1200 and 1) or 0.6) or Clamp(M.shares.exp * 3),
    }
    -- little evidence yet: trust what earlier matches taught; later, what this match shows
    local learned = 0.4
    if t < 300 and (M.attacks + M.raids) == 0 then learned = 0.7 end
    if t > 600 then learned = 0.2 end
    local best, bestV = 'balanced', 0.35
    for _, k in ipairs(STYLE_KEYS) do
        M.raw[k] = raw[k]
        local v = raw[k]
        if M.prior then v = v * (1 - learned) + (M.prior[k] or 0) * learned end
        M.style[k] = v
        if v > bestV then best, bestV = k, v end
    end
    M.dominant = best
    M.updated = t
end

-- what goes to the panel
function CPAIModelSummary()
    local M = Model()
    local parts = {}
    local list = {}
    for _, k in ipairs(STYLE_KEYS) do table.insert(list, { k = k, v = M.style[k] or 0 }) end
    table.sort(list, function(a, b) return a.v > b.v end)
    for i = 1, 3 do
        if list[i].v >= 0.2 then table.insert(parts, STYLE_LABEL[list[i].k] .. ' ' .. math.floor(list[i].v * 100) .. '%') end
    end
    local first = M.firstAttack or M.expectedAttack
    local firstText = 'ainda nao atacou'
    if first then firstText = math.floor(first / 60) .. ':' .. string.format('%02d', math.floor(math.mod(first, 60))) end
    return {
        style = table.getn(parts) > 0 and table.concat(parts, ', ') or 'ainda aprendendo',
        dominant = STYLE_LABEL[M.dominant] or M.dominant,
        firstAttack = firstText,
        attacks = M.attacks, raids = M.raids, games = M.games,
    }
end

-- what goes to Game.prefs: this match only (the interface blends it with the earlier ones)
function CPAIModelMemory()
    local M = Model()
    local style = {}
    for _, k in ipairs(STYLE_KEYS) do style[k] = math.floor((M.raw[k] or 0) * 100 + 0.5) / 100 end
    return {
        style = style,
        firstAttack = M.firstAttack and math.floor(M.firstAttack) or false,
        route = Top(M.route, 12), hit = Top(M.hit, 12), expand = Top(M.expand, 12),
        held = Top(M.held or {}, 12), lost = Top(M.lost or {}, 12),
        genes = CPAI.GenesAverage and CPAI.GenesAverage() or nil,
    }
end

-- the hottest cell of a heat map within a band of distances from a point; `owner` keeps only the
-- cells closer to that commander's home than to any other AI's home (its own territory)
local function Hottest(map, from, minD, maxD, minW, owner)
    local best, bestW, bestKey = false, minW or 1, false
    for key, w in map do
        if w > bestW then
            local p = CellCenter(key)
            local d = Dist(p, from)
            local mine = true
            if owner then
                for army, other in CPAI.commanders do
                    if army ~= owner.army and Dist(p, other.home) < d then
                        mine = false
                        break
                    end
                end
            end
            if mine and d >= minD and d <= maxD then best, bestW, bestKey = p, w, key end
        end
    end
    return best, bestW, bestKey
end

-- ---------------------------------------------------------------- the commander of one AI
local Commander = {}

local function Squad(name)
    return { name = name, state = 'hold', units = {}, members = {} }
end

function Commander.New(brain, home)
    local key = CFG.personality
    if key == 'mixed' or not PERSONALITIES[key] then
        key = PERSONALITY_ORDER[Rand(1, table.getn(PERSONALITY_ORDER))] or 'balanced'
    end
    local ok, faction = pcall(brain.GetFactionIndex, brain)
    if not ok or not UNITS[faction] then faction = 1 end
    local self = {
        brain = brain,
        army = brain:GetArmyIndex(),
        home = home,
        faction = faction,
        units = UNITS[faction],
        personalityKey = key,
        P = PERSONALITIES[key],
        squads = {
            main = Squad('main'), raid = Squad('raid'), fleet = Squad('fleet'), drop = Squad('drop'),
            fighters = Squad('fighters'), bombers = Squad('bombers'), gunships = Squad('gunships'),
            scouts = Squad('scouts'), guard = Squad('guard'), ambush = Squad('ambush'),
        },
        platoon = false,
        difficulty = brain.DifficultyLevel or 2,
        cooldowns = {},
        built = {},
        adaptive = 0, -- -1 = holding back, 0 = normal, 1 = pressing harder
        plan = 'preparando',
        intel = { air = 0, land = 0, naval = 0, towers = 0 },
        memo = {},
        kills = {},   -- where our units died (cells, fading)
        track = {},   -- unit -> last position, to notice losses
        needs = {},   -- research already asked for
        paths = {}, pathStats = {}, pathBroken = {},
        enemies = {}, facesHuman = false,
        failures = 0,
        journal = {}, -- what the AI did, for the panel (newest first)
        tally = { attacks = 0, won = 0, retreats = 0, defended = 0, districts = 0, lost = 0, fronts = 0, siege = 0, helped = 0 },
        lossBy = { air = 0, towers = 0, land = 0 }, -- what has been killing our units (fading)
    }
    if key == 'naval' and faction == 3 then
        -- Illuminate has no navy
        self.personalityKey = 'balanced'
        self.P = PERSONALITIES.balanced
    end
    self.ratio = Commander.BaseRatio(self)
    CPAI.commanders[self.army] = self
    return self
end

function Commander.BaseRatio(self)
    local r = self.P.ratio
    if self.difficulty <= 1 then r = r - 0.2 end
    if CFG.level >= 2 then r = r + 0.15 end
    return r
end

-- how much stronger than the target the army must be: the personality, the adaptive mode, the
-- Alsyper aggression gene and the right-moment window
function Commander.Ratio(self)
    local r = self.ratio * (1.3 - 0.3 * Commander.Gene(self, 'aggression'))
    if Commander.InWindow(self) then r = r * 0.8 end
    r = r - ((CPAI.strength or 1) - 1) * 0.5
    return math.max(1.0, r)
end

function Commander.Cooldown(self, key, seconds)
    local t = Now()
    if (self.cooldowns[key] or 0) > t then return false end
    self.cooldowns[key] = t + seconds
    return true
end

-- the player model, only for AIs that fight a human
function Commander.M(self)
    local M = CPAI.model
    if M and M.humans > 0 and self.facesHuman then return M end
    return false
end

function Commander.Allies(self)
    local list = {}
    if not CFG.team then return list end
    for army, other in CPAI.commanders do
        if army ~= self.army and Allied(self.army, army) and not Defeated(other.brain) then table.insert(list, other) end
    end
    return list
end

function Commander.NearestEnemyStart(self)
    local best, bestD = false, 0
    for _, idx in ipairs(self.enemies) do
        local A = CPAI.snap and CPAI.snap.armies[idx]
        if A then
            local ok, x, z = pcall(A.brain.GetArmyStartPos, A.brain)
            if ok and x then
                local p = Point(x, z)
                local d = Dist(self.home, p)
                if not best or d < bestD then best, bestD = p, d end
            end
        end
    end
    return best, bestD
end

-- where the army waits: the route the human uses (with hysteresis), else a third of the way or a
-- nearby expansion area; refined to the narrowest, highest place around it
function Commander.Staging(self)
    if self.memo.staging then return self.memo.staging end
    local enemy, d = Commander.NearestEnemyStart(self)
    if not enemy or d <= 0 then return self.home end
    local M = Commander.M(self)
    local t = Now()
    if M then
        -- a rush is expected: wait close to home until the usual attack time has passed
        if not self.rushCheckAt or t - self.rushCheckAt > 60 then
            self.rushCheckAt = t
            local expected = M.firstAttack or M.expectedAttack
            self.rushHold = (M.style.rush or 0) > 0.5 and t < (expected or 420) + 90
        end
        if self.rushHold then
            self.memo.staging = Toward(self.home, enemy, 45)
            return self.memo.staging
        end
    end
    local raw = false
    if M then
        local spot, w, key = Hottest(M.route, self.home, 60, math.min(d * 0.55, 220), 1.5)
        if spot then
            local current = self.routeKey and (M.route[self.routeKey] or 0) or 0
            if self.routeKey and self.routeKey ~= key and current > 0 and w <= current * 1.3 then
                spot = CellCenter(self.routeKey)
            else
                self.routeKey = key
            end
            raw = spot
        end
    end
    if not raw then
        -- a finished bastion facing the enemy: the army gathers in front of its towers
        local bastion, bd = false, 0
        for _, dd in (self.districts or {}) do
            if dd.role == 'bastion' and dd.step > 3 and not dd.island then
                local de = Dist(dd.pos, enemy)
                if not bastion or de < bd then bastion, bd = dd, de end
            end
        end
        if bastion then raw = Toward(bastion.pos, enemy, 25) end
    end
    if not raw then
        self.routeKey = false
        raw = Toward(self.home, enemy, math.min(150, d * 0.33))
        for _, m in Markers().expansion do
            if Dist(m, raw) < 60 and Dist(m, self.home) < Dist(m, enemy) then
                raw = Point(m[1], m[3])
                break
            end
        end
    end
    local key = CellKey(raw)
    if self.ambushKey ~= key or not self.ambush or t - (self.ambushAt or 0) > 60 then
        self.ambushKey = key
        self.ambushAt = t
        local ok, spot = pcall(AmbushSpot, raw, enemy, self.kills)
        self.ambush = ok and spot or raw
    end
    self.memo.staging = self.ambush
    return self.ambush
end

function Commander.MinUnits(self)
    local t = Now()
    local n = 6 + math.floor(t / 120)
    if CFG.level >= 2 then n = 8 + math.floor(t / 100) end
    n = math.floor(n * self.P.size + 0.5)
    if self.adaptive > 0 then n = n - 2 end
    if self.adaptive < 0 then n = n + 4 end
    n = n * (0.6 + 0.4 * Commander.Gene(self, 'patience'))
    if Commander.InWindow(self) then n = n * 0.75 end
    return math.max(4, math.min(math.floor(n + 0.5), 34))
end

function Commander.Platoon(self)
    local ok, exists = pcall(self.brain.PlatoonExists, self.brain, self.platoon)
    if not (self.platoon and ok and exists) then
        local ok2, p = pcall(self.brain.MakePlatoon, self.brain, '', '')
        self.platoon = ok2 and p or false
    end
    return self.platoon
end

function Commander.List(self, cat)
    return ListOf(self.brain, cat)
end

-- enemy ground strength (units and towers), mobile only, and anti-air around a point
function Commander.Danger(self, pos, radius)
    local key = 'g' .. math.floor(pos[1] / 10) .. ':' .. math.floor(pos[3] / 10) .. ':' .. radius
    local v = self.memo[key]
    if v == nil then
        local S = Snapshot()
        v = SumAround(S, self.enemies, 'ground', pos, radius) + SumAround(S, self.enemies, 'towers', pos, radius)
        self.memo[key] = v
    end
    return v
end

function Commander.MobileDanger(self, pos, radius)
    return SumAround(Snapshot(), self.enemies, 'ground', pos, radius)
end

function Commander.AntiAir(self, pos, radius)
    local key = 'a' .. math.floor(pos[1] / 10) .. ':' .. math.floor(pos[3] / 10) .. ':' .. radius
    local v = self.memo[key]
    if v == nil then
        v = SumAround(Snapshot(), self.enemies, 'aa', pos, radius)
        self.memo[key] = v
    end
    return v
end

-- can these units walk (or sail) there? Asks the pathfinder for a point just short of the target
-- (buildings block their own spot), caches the answer for 30 s, and checks once that the
-- pathfinder answers at all (if it says no even right next to the unit, it is not trusted)
function Commander.CanReach(self, units, pos, layer)
    local u = units[1]
    if not u then return false end
    layer = layer or 'land'
    if self.pathBroken[layer] then return true end
    local from = u:GetPosition()
    local function ask(goal)
        local ok, res = pcall(function() return u:GetNavigator():CanPathToGoal(goal) end)
        if not ok then return nil end
        return res and true or false
    end
    local st = self.pathStats[layer]
    if not st then
        local near = ask(Point(from[1] + 4, from[3] + 4))
        if near == nil or near == false then
            -- no answer, or "no" right next to the unit: the pathfinder cannot be trusted
            self.pathBroken[layer] = true
            return true
        end
        st = { checked = true }
        self.pathStats[layer] = st
    end
    local goal = Toward(pos, from, 15)
    local key = layer .. CellKey(goal)
    local t = Now()
    local c = self.paths[key]
    if c and t - c.t < 30 then return c.ok end
    local res = ask(goal)
    if res == nil then res = true end
    self.paths[key] = { t = t, ok = res }
    return res
end

-- ---------------------------------------------------------------- recruiting
function Commander.AirRole(self, u)
    local c = Categories()
    local fighter = Is(c.fighter, u) or (Is(c.antiair, u) and not Is(c.gunship, u))
    local bomber = Is(c.bomber, u)
    if fighter and bomber then
        -- Cybran and Illuminate fighter-bombers: keep both jobs covered
        local f = table.getn(self.squads.fighters.units)
        local b = table.getn(self.squads.bombers.units)
        if b * 2 < f then return 'bombers' end
        return 'fighters'
    end
    if fighter then return 'fighters' end
    if bomber then return 'bombers' end
    if Is(c.gunship, u) or Power(u, true) > 0 then return 'gunships' end
    return 'scouts'
end

-- one order for a whole squad, remembered so that reinforcements join the same task
function Commander.Command(self, squad, units, kind, pos, queue)
    Order(units, kind, pos, queue)
    if not queue then squad.objective = { kind = kind, pos = pos } end
end

-- takes finished combat units into the commander's squads (out of the engine's attack platoons)
function Commander.Recruit(self)
    local c = Categories()
    local fresh = {}
    local raidCount = table.getn(self.squads.raid.units)
    local function add(squad, u)
        u.CPSquad = squad
        fresh[squad] = fresh[squad] or {}
        table.insert(fresh[squad], u)
    end
    for _, u in ipairs(Commander.List(self, c.army)) do
        if not u.CPSquad and Ready(u) then
            if CFG.raids and raidCount < self.P.raid * Commander.Gene(self, 'harass') and Speed(u) >= 4 and not Is(c.experimental, u) and not Is(c.indirect, u) then
                raidCount = raidCount + 1
                add('raid', u)
            else
                add('main', u)
            end
        end
    end
    for _, u in ipairs(Commander.List(self, c.fleet)) do
        if not u.CPSquad and Ready(u) then add('fleet', u) end
    end
    if CFG.air then
        for _, u in ipairs(Commander.List(self, c.air)) do
            if not u.CPSquad and Ready(u) then add(Commander.AirRole(self, u), u) end
        end
    end
    local plat = Commander.Platoon(self)
    for name, units in fresh do
        if plat then pcall(self.brain.AssignUnitsToPlatoon, self.brain, plat, units, 'Attack', 'None') end
        local sq = self.squads[name]
        local obj = sq.objective
        if name == 'main' and sq.state == 'attack' and sq.target and sq.center then
            -- join the fight directly when the way to the front is safe
            local from = Centroid(units) or self.home
            local mid = Point((from[1] + sq.center[1]) / 2, (from[3] + sq.center[3]) / 2)
            if Commander.Danger(self, mid, 50) < PowerOf(units) and Commander.CanReach(self, units, sq.target, 'land') then
                Order(units, 'attack', sq.target)
            else
                Order(units, 'move', sq.rally or Commander.Staging(self))
            end
        elseif obj then
            Order(units, obj.kind, obj.pos)
        else
            Order(units, 'move', Commander.Staging(self))
        end
    end
end

-- live members; badly damaged units go home and come back after a while or when repaired
function Commander.Members(self, squad)
    local list, hurt = {}, {}
    local exp = Categories().experimental
    local t = Now()
    for _, u in ipairs(squad.units) do
        if Alive(u) and u.CPSquad == squad.name and not u.CPDropping then
            local f = HealthFraction(u)
            if u.CPWounded then
                if f > 0.5 or t - u.CPWounded > 75 then u.CPWounded = nil end
            elseif (f < 0.3 or (f < 0.5 and CPVeteran(u) >= 2)) and not Is(exp, u) and squad.name ~= 'drop' then
                u.CPWounded = t
                table.insert(hurt, u)
            end
            if not u.CPWounded then table.insert(list, u) end
        end
    end
    if table.getn(hurt) > 0 then Order(hurt, 'move', self.home) end
    return list
end

function Commander.Collect(self)
    local c = Categories()
    for _, sq in self.squads do sq.units = {} end
    for _, cat in { c.army, c.fleet, c.air } do
        for _, u in ipairs(Commander.List(self, cat)) do
            if u.CPSquad and Alive(u) then
                local sq = self.squads[u.CPSquad]
                if sq then table.insert(sq.units, u) end
            end
        end
    end
    for _, sq in self.squads do sq.members = Commander.Members(self, sq) end
    -- losses: units we were tracking that died mark a dangerous place (fades over time)
    for k, w in self.kills do
        w = w * 0.98
        if w < 0.05 then self.kills[k] = nil else self.kills[k] = w end
    end
    local track = {}
    for _, sq in self.squads do
        for _, u in ipairs(sq.units) do track[u] = u:GetPosition() end
    end
    for k, v in self.lossBy do self.lossBy[k] = v * 0.97 end
    local S = Snapshot()
    for u, pos in self.track do
        if not track[u] and not Alive(u) then
            local key = CellKey(pos)
            self.kills[key] = math.min(20, (self.kills[key] or 0) + 1)
            -- what killed it: enemy aircraft, towers or ground units around the place
            local air = 0
            for _, idx in ipairs(self.enemies) do
                for _, a in ipairs(S.armies[idx] and S.armies[idx].air or {}) do
                    if Dist(a.pos, pos) < 45 then air = air + 1 end
                end
            end
            local towers = SumAround(S, self.enemies, 'towers', pos, 40)
            local ground = SumAround(S, self.enemies, 'ground', pos, 40)
            if air >= 2 and air * 2 >= ground then self.lossBy.air = self.lossBy.air + 1
            elseif towers > ground then self.lossBy.towers = self.lossBy.towers + 1
            else self.lossBy.land = self.lossBy.land + 1 end
        end
    end
    self.track = track
end

-- against a raider: a small guard stays where the human usually strikes; given back otherwise
function Commander.AssignGuard(self)
    local M = Commander.M(self)
    local guard = self.squads.guard
    local raider = M and (M.style.raider or 0) or 0
    if raider < 0.35 then
        for _, u in ipairs(guard.units) do u.CPSquad = 'main' end
        return
    end
    if raider <= 0.5 then return end
    local have = table.getn(guard.members)
    local main = self.squads.main.members
    if have >= 4 or table.getn(main) <= Commander.MinUnits(self) then return end
    local exp = Categories().experimental
    local moved = 0
    for i = table.getn(main), 1, -1 do
        local u = main[i]
        if moved >= 4 - have then break end
        if not Is(exp, u) then
            u.CPSquad = 'guard'
            table.remove(main, i)
            table.insert(guard.members, u)
            table.insert(guard.units, u)
            moved = moved + 1
        end
    end
    if moved > 0 then guard.post = false end
end

-- ---------------------------------------------------------------- targets and threats
-- places worth taking: enemy structures grouped in cells of 40, valued by what they are
function Commander.Targets(self)
    if self.memo.targets then return self.memo.targets end
    local S = Snapshot()
    local cells = {}
    for _, idx in ipairs(self.enemies) do
        local A = S.armies[idx]
        for _, s in ipairs(A and A.structs or {}) do
            local key = math.floor(s.pos[1] / 40) .. ':' .. math.floor(s.pos[3] / 40)
            local cell = cells[key]
            if not cell then
                cell = { pos = s.pos, value = 0, extractors = 0, artillery = 0, shields = {}, mines = {} }
                cells[key] = cell
            end
            if s.kind == 'shield' then table.insert(cell.shields, s.u) end
            if s.kind == 'expfactory' then cell.value = cell.value + 6 end
            if s.kind == 'extractor' then
                table.insert(cell.mines, s.pos)
                cell.value = cell.value + 3
                cell.extractors = cell.extractors + 1
            elseif s.kind == 'factory' then
                cell.value = cell.value + 4
            elseif s.kind == 'artillery' then
                cell.value = cell.value + 3
                cell.artillery = cell.artillery + 1
            else
                cell.value = cell.value + 1
            end
        end
    end
    local out = {}
    for _, cell in cells do table.insert(out, cell) end
    self.memo.targets = out
    return out
end

-- our structures grouped in cells of 60 (factories, extractors, defence)
function Commander.Clusters(self)
    local S = Snapshot()
    local A = S.armies[self.army]
    local centers = {}
    for _, s in ipairs(A and A.structs or {}) do
        local key = math.floor(s.pos[1] / 60) .. ':' .. math.floor(s.pos[3] / 60)
        local cl = centers[key]
        if not cl then
            cl = { key = key, pos = s.pos, extractors = 0, factories = 0, count = 0, defense = 0 }
            centers[key] = cl
        end
        cl.count = cl.count + 1
        if s.kind == 'extractor' then cl.extractors = cl.extractors + 1 end
        if s.kind == 'factory' then cl.factories = cl.factories + 1 end
        cl.defense = cl.defense + s.defense
    end
    return centers
end

-- a real attack on our places: enemy mobile units only (not towers), above a small threshold
-- (a lone engineer or scout is left to the towers and the guard)
function Commander.Threat(self, clusters)
    local worst, worstPower, worstKey = false, 0, false
    for key, cl in clusters do
        local power = Commander.MobileDanger(self, cl.pos, 55)
        cl.threat = power
        if power >= 3 and power > worstPower then worst, worstPower, worstKey = cl.pos, power, key end
    end
    return worst, worstPower, worstKey
end

-- the nearest place with our towers (or home) to fall back to
function Commander.SafeSpot(self, from)
    local best, bestD = self.home, Dist(from, self.home)
    local homeD = Dist(from, self.home)
    for _, cl in (self.lastClusters or {}) do
        if cl.defense >= 6 then
            local d = Dist(from, cl.pos)
            if d < bestD then best, bestD = cl.pos, d end
        end
    end
    -- a bastion between us and home: fall back behind its towers
    for _, dd in (self.districts or {}) do
        if (dd.role == 'bastion' or dd.role == 'workshop') and dd.step > 3 and Dist(dd.pos, self.home) < homeD then
            local d = Dist(from, dd.pos)
            if d < bestD then best, bestD = Toward(dd.pos, self.home, 15), d end
        end
    end
    return best
end

-- an ally under attack nearby asks for help
function Commander.AllyThreat(self)
    for _, ally in Commander.Allies(self) do
        if ally.threatPos and (ally.threatPower or 0) > 0 and Dist(ally.threatPos, self.home) < 400 then
            return ally.threatPos, ally.threatPower
        end
    end
    -- a human on our side under attack at home or at an expansion
    local S = Snapshot()
    for idx, A in S.armies do
        if A.human and Allied(self.army, idx) then
            for _, st in ipairs(A.structs) do
                if st.kind == 'factory' or st.kind == 'extractor' then
                    local p = Commander.MobileDanger(self, st.pos, 50)
                    if p >= 4 and Dist(st.pos, self.home) < 450 then
                        if Commander.Cooldown(self, 'helpnote', 60) then
                            self.tally.helped = self.tally.helped + 1
                            Commander.Note(self, 'indo ajudar o aliado humano atacado')
                        end
                        return st.pos, p
                    end
                end
            end
        end
    end
    return false, 0
end

function Commander.AllyTargetBonus(self, pos)
    for _, ally in Commander.Allies(self) do
        local t = ally.squads.main.target
        if t and ally.squads.main.state == 'attack' and Dist(t, pos) < 80 then return 1.6 end
    end
    return 1
end

function Commander.PickTarget(self, squad, power, opts)
    opts = opts or {}
    local best, bestScore, bestRisk = false, 0, 0
    local origin = squad.center or Centroid(squad.members) or self.home
    local ratio = opts.ratio or Commander.Ratio(self)
    local layer = opts.water and 'sea' or 'land'
    local M = Commander.M(self)
    -- the most promising first, so the (cached) path checks stop early
    local scored = {}
    for _, cell in Commander.Targets(self) do
        if not (opts.avoid and Dist(cell.pos, opts.avoid) < 120) then
            local risk = Commander.Danger(self, cell.pos, 45) + (self.kills[CellKey(cell.pos)] or 0) * 1.5
            -- with the human ally's army already there, our share of the fight is smaller
            local helpers = (self.joinPos and Dist(self.joinPos, cell.pos) < 90) and (self.joinPower or 0) or 0
            if power + helpers >= risk * ratio and power > 0 then
                local d = Dist(origin, cell.pos)
                local score = cell.value * 10 / (1 + risk) / (1 + d / 400)
                score = score * Commander.AllyTargetBonus(self, cell.pos)
                if M then
                    -- the places the human keeps expanding to are worth denying
                    score = score * (1 + math.min(1, (M.expand[CellKey(cell.pos)] or 0) / 10))
                end
                -- siege: extractors far from the owner's base cut the economy before the assault
                if cell.extractors > 0 and squad.name ~= 'drop' then
                    local far = true
                    for _, e in Commander.EnemyHomes(self) do
                        if Dist(e, cell.pos) < 150 then far = false break end
                    end
                    if far then score = score * 1.6 end
                end
                -- an ally human attacking there: go together
                if self.joinPos and Dist(self.joinPos, cell.pos) < 90 then score = score * 2.5 end
                -- the experimental factory the scouts saw: before it finishes
                if self.expStrike and Dist(self.expStrike, cell.pos) < 60 then score = score * 4 end
                if squad.name == 'raid' then
                    -- raiders only go where little can shoot back
                    if risk > (opts.raidRisk or 1) or cell.extractors == 0 then score = 0 end
                end
                if score > 0 then table.insert(scored, { cell = cell, score = score, risk = risk }) end
            end
        end
    end
    table.sort(scored, function(a, b) return a.score > b.score end)
    for i = 1, math.min(6, table.getn(scored)) do
        local e = scored[i]
        if opts.noPath or Commander.CanReach(self, squad.members, e.cell.pos, layer) then
            best, bestScore, bestRisk = e.cell.pos, e.score, e.risk
            break
        end
    end
    -- the fleet also hunts enemy ships it can reach
    if opts.water and not best then
        local S = Snapshot()
        local checked = 0
        for _, idx in ipairs(self.enemies) do
            for _, m in ipairs(S.armies[idx] and S.armies[idx].mobile or {}) do
                if m.naval then
                    checked = checked + 1
                    if checked > 8 then break end
                    local risk = Commander.Danger(self, m.pos, 45)
                    if power >= risk * ratio and Commander.CanReach(self, squad.members, m.pos, 'sea') then
                        return m.pos, risk
                    end
                end
            end
        end
    end
    return best, bestRisk
end

-- ---------------------------------------------------------------- army tactics
-- focus fire on the most damaged dangerous enemy in reach; artillery on high ground behind the
-- front; units on a flank or escorting an experimental keep their orders
function Commander.Micro(self, squad, center)
    if not CFG.micro or not center then return end
    local c = Categories()
    local weakest, weakestF, count = false, 2, 0
    for _, e in ipairs(Around(self.brain, c.mobile, center, 40, 'Enemy')) do
        -- worth a focus: a real combat unit (rated by its full strength, not its current health)
        local f = HealthFraction(e)
        if Ready(e) and not Is(c.enemyAir, e) and not Is(c.engineerAny, e) and Power(e) >= 0.35 + 0.65 * f then
            count = count + 1
            if f < weakestF then weakest, weakestF = e, f end
        end
    end
    local front, arty = {}, {}
    for _, u in ipairs(squad.members) do
        if Is(c.indirect, u) and not Is(c.experimental, u) then
            table.insert(arty, u)
        elseif not u.CPNoMicro then
            table.insert(front, u)
        end
    end
    local focusAlive = squad.focus and Alive(squad.focus)
    local refocus = not focusAlive or Dist(squad.focus:GetPosition(), center) > 45
        or (weakest and weakest ~= squad.focus and weakestF < (squad.focusF or 1) - 0.2)
    if weakest and count >= 2 and refocus then
        squad.focus = weakest
        squad.focusF = weakestF
        -- two thirds focus the target, the rest keep the attack-move
        local n = math.ceil(table.getn(front) * 2 / 3)
        local focus = {}
        for i = 1, n do table.insert(focus, front[i]) end
        pcall(IssueClearCommands, focus)
        pcall(IssueAttack, focus, weakest)
        if squad.target then Order(focus, 'attack', squad.target, true) end
    end
    if table.getn(arty) > 0 then
        local behind = Toward(center, self.home, 22)
        if not squad.artyAt or Dist(squad.artyAt, behind) > 12 then
            local ok, spot = pcall(HighSpot, behind)
            squad.artyAt = behind
            Order(arty, 'attack', ok and spot or behind)
        end
    end
end

local function ClearTactics(members)
    for _, u in ipairs(members) do u.CPNoMicro = nil end
end

-- experimentals lead; the rest of the army guards them
function Commander.Escort(self, squad, target)
    local c = Categories()
    local exps, others = {}, {}
    for _, u in ipairs(squad.members) do
        if Is(c.experimental, u) then table.insert(exps, u) else table.insert(others, u) end
    end
    if table.getn(exps) == 0 then return false end
    -- an experimental never goes without anti-air when the enemy has an air force
    local aa = 0
    for _, u in ipairs(others) do if Is(c.antiair, u) then aa = aa + 1 end end
    if aa < 3 and (self.intel.air or 0) > 3 and Commander.Cooldown(self, 'escortaa', 50) then
        if Commander.Queue(self, self.units.aaLand, 3) or Commander.Queue(self, self.units.fighter, 3) then
            Commander.Note(self, 'antiaereo para escoltar o experimental')
        end
    end
    Commander.Command(self, squad, exps, 'attack', target)
    if table.getn(others) > 0 then
        for _, u in ipairs(others) do u.CPNoMicro = true end
        pcall(IssueClearCommands, others)
        pcall(IssueGuard, others, exps[1])
    end
    return true
end

-- a formation: tanks and bots in front, artillery shooting from behind, anti-air in the middle
-- covering the front line
function Commander.Formation(self, squad, members, target, center)
    local c = Categories()
    local front, arty, aa = {}, {}, {}
    for _, u in ipairs(members) do
        if Is(c.indirect, u) and not Is(c.experimental, u) then table.insert(arty, u)
        elseif Is(c.antiair, u) and not Is(c.experimental, u) and Power(u) < 1 then table.insert(aa, u)
        else table.insert(front, u) end
    end
    if table.getn(front) < 3 or (table.getn(arty) == 0 and table.getn(aa) == 0) then return false end
    if squad then Commander.Command(self, squad, front, 'attack', target) else Order(front, 'attack', target) end
    -- a shield over the target: the artillery hits the shield generator first
    local shield = false
    for _, cell in Commander.Targets(self) do
        if Dist(cell.pos, target) < 40 then
            for _, sh in ipairs(cell.shields or {}) do if Alive(sh) then shield = sh break end end
        end
        if shield then break end
    end
    if table.getn(arty) > 0 then
        -- artillery stops at its range from the target, behind the front line
        local from = center or self.home
        if shield then
            for _, u in ipairs(arty) do u.CPNoMicro = true end
            pcall(IssueClearCommands, arty)
            pcall(IssueAttack, arty, shield)
            Order(arty, 'attack', target, true)
            Commander.Note(self, 'artilharia derrubando o escudo antes do ataque')
        else
            Order(arty, 'attack', Toward(target, from, 32))
        end
    end
    self.breakShield = shield and target or false
    if table.getn(aa) > 0 then
        for _, u in ipairs(aa) do u.CPNoMicro = true end
        pcall(IssueClearCommands, aa)
        pcall(IssueGuard, aa, front[1])
    end
    return true
end

-- a very large army splits and hits two places far apart at the same time
function Commander.TwoFronts(self, squad, power, target, center)
    local members = squad.members
    local n = table.getn(members)
    if n < Commander.MinUnits(self) * 3 then return false end
    local second = Commander.PickTarget(self, squad, power * 0.5, { avoid = target })
    if not second or Dist(second, target) < 200 then return false end
    local a, b = {}, {}
    for i, u in ipairs(members) do
        if math.mod(i, 2) == 0 then table.insert(b, u) else table.insert(a, u) end
    end
    for _, u in ipairs(b) do u.CPNoMicro = true end
    if not Commander.Formation(self, squad, a, target, center) then Commander.Command(self, squad, a, 'attack', target) end
    if not Commander.Formation(self, false, b, second, center) then Order(b, 'attack', second) end
    squad.second = second
    self.tally.fronts = self.tally.fronts + 1
    Commander.Note(self, 'ataque em duas frentes')
    return true
end

-- half the army comes from the flank
function Commander.Pincer(self, squad, center, target)
    local members = squad.members
    local n = table.getn(members)
    if not self.P.pincer or n < Commander.MinUnits(self) * 2 or Dist(center, target) < 120 then return false end
    local dx, dz = target[1] - center[1], target[3] - center[3]
    local len = math.sqrt(dx * dx + dz * dz)
    if len <= 0 then return false end
    dx, dz = dx / len, dz / len
    local side = 1
    if math.mod(self.army, 2) == 0 then side = -1 end
    local flank = Point(target[1] - dx * 45 - dz * 75 * side, target[3] - dz * 45 + dx * 75 * side)
    local a, b = {}, {}
    for i, u in ipairs(members) do
        if math.mod(i, 2) == 0 then table.insert(b, u) else table.insert(a, u) end
    end
    if not Commander.CanReach(self, b, flank, 'land') then return false end
    for _, u in ipairs(b) do u.CPNoMicro = true end
    Commander.Command(self, squad, a, 'attack', target)
    Order(b, 'move', flank)
    Order(b, 'attack', target, true)
    return true
end

function Commander.Lead(self, squad, threatPos, threatPower)
    local members = squad.members
    local count = table.getn(members)
    if count == 0 then
        squad.state = 'hold'
        squad.ordered = false
        return
    end
    local power = PowerOf(members)
    local center = Centroid(members)
    squad.center = center
    local t = Now()
    local water = squad.name == 'fleet'
    local layer = water and 'sea' or 'land'

    -- 1. defend what is ours (or an ally nearby): intercept if we can win, otherwise fall back home
    if threatPos and squad.name ~= 'raid' and squad.name ~= 'drop' and (not water or Commander.CanReach(self, members, threatPos, 'sea')) then
        if power >= threatPower * 0.8 then
            if squad.state ~= 'defend' or Dist(squad.target or threatPos, threatPos) > 40 then
                ClearTactics(members)
                squad.state = 'defend'
                squad.target = threatPos
                Commander.Command(self, squad, members, 'attack', threatPos)
                Log(self.brain, squad.name .. ' defends')
                if squad.name == 'main' then
                    self.tally.defended = self.tally.defended + 1
                    Commander.Note(self, 'defendendo um ataque')
                end
            end
            return
        end
        if squad.state ~= 'home' then
            ClearTactics(members)
            squad.state = 'home'
            squad.target = false
            Commander.Command(self, squad, members, 'move', self.home)
        end
        return
    elseif squad.state == 'defend' or squad.state == 'home' then
        -- the attack was beaten off: strike back while the enemy army is weak
        if squad.state == 'defend' then squad.counterUntil = t + 40 end
        squad.state = 'hold'
        squad.ordered = false
    end

    -- 2. in a fight: retreat if it turned bad, look for the next target when it is won
    if squad.state == 'attack' and center then
        local enemyHere = Commander.Danger(self, center, 50)
        local oursHere = 0
        for _, u in ipairs(members) do
            if Dist(u:GetPosition(), center) < 50 then oursHere = oursHere + Power(u) end
        end
        if enemyHere > oursHere * 1.2 and squad.name ~= 'drop' then
            ClearTactics(members)
            squad.state = 'retreat'
            squad.until_ = t + 25
            squad.target = false
            Commander.Command(self, squad, members, 'move', Commander.SafeSpot(self, center))
            Log(self.brain, squad.name .. ' retreats')
            if squad.name == 'main' then
                self.tally.retreats = self.tally.retreats + 1
                Commander.Note(self, 'recuou para as torres')
                Commander.Say(self, 'Bem jogado. Volto mais forte.')
            end
            return
        end
        local won = squad.target and Dist(center, squad.target) < 30 and Commander.Danger(self, squad.target, 45) <= 0.5
        if won or t - (squad.attackSince or t) > 150 then
            if won and squad.name == 'main' then
                self.tally.won = self.tally.won + 1
                Commander.Note(self, 'venceu a luta e destruiu o alvo')
                Commander.Say(self, 'Essa foi minha.')
                self.stealSpots = self.stealSpots or {}
                for _, mp in ipairs(squad.mines or {}) do table.insert(self.stealSpots, mp) end
                Commander.Reclaim(self, squad.target)
            end
            squad.second = false
            ClearTactics(members)
            squad.target = false
            squad.state = 'hold'
            squad.ordered = false
        else
            if squad.name == 'main' then Commander.Micro(self, squad, center) end
            return
        end
    end
    if squad.state == 'retreat' and t < (squad.until_ or 0) then return end

    -- 3. choose a target the army can actually beat; gather first, then strike together
    local minUnits = Commander.MinUnits(self)
    if squad.name == 'raid' then minUnits = 2 end
    if squad.name == 'drop' then minUnits = 1 end
    if water then minUnits = math.max(3, math.floor(minUnits * (self.P.fleet or 0.5))) end
    if squad.counterUntil and t < squad.counterUntil then
        minUnits = math.max(3, math.floor(minUnits * 0.6))
        self.plan = 'contra-ataque'
    end
    -- an ally human already fighting: no need to wait for the full army
    if self.joinPos and squad.name == 'main' then minUnits = math.max(3, math.floor(minUnits * 0.6)) end
    if count >= minUnits then
        local opts = { water = water }
        if squad.name == 'raid' and self.squads.main.state == 'attack' and self.squads.main.target then
            -- diversion: hit something far from the main attack, even a little defended
            opts.avoid = self.squads.main.target
            opts.raidRisk = 3
        end
        if squad.name == 'drop' then opts.noPath = true end
        local target = Commander.PickTarget(self, squad, power, opts)
        if not target and count >= minUnits * 3 then
            -- a very large army accepts an even fight
            opts.ratio = 1.0
            target = Commander.PickTarget(self, squad, power, opts)
        end
        if target then
            if squad.name ~= 'raid' and squad.name ~= 'drop' and center and Spread(members, center) > 35 and squad.state ~= 'gather' then
                squad.state = 'gather'
                squad.gatherUntil = t + 40
                squad.rally = center
                Commander.Command(self, squad, members, 'move', center)
                return
            end
            if squad.state == 'gather' and center and Spread(members, center) > 35 and t < (squad.gatherUntil or 0) then
                return
            end
            if squad.name == 'main' and squad.state ~= 'gather' and Commander.Decoy(self, squad, target) then return end
            squad.state = 'attack'
            squad.attackSince = t
            squad.target = target
            -- the enemy extractors there: ours once the place is taken
            squad.mines = {}
            for _, cell in Commander.Targets(self) do
                if Dist(cell.pos, target) < 40 then
                    for _, mp in ipairs(cell.mines or {}) do table.insert(squad.mines, mp) end
                end
            end
            if squad.name == 'main' then
                Commander.Say(self, ({ 'La vou eu.', 'Vi uma brecha na sua defesa.', 'Prepare-se.', 'Agora e a minha vez.' })[math.mod(self.tally.attacks, 4) + 1])
                self.tally.attacks = self.tally.attacks + 1
                local siege = false
                for _, cell in Commander.Targets(self) do
                    if Dist(cell.pos, target) < 30 and cell.extractors > 0 and cell.value <= cell.extractors * 3 + 2 then siege = true break end
                end
                if siege then
                    self.tally.siege = self.tally.siege + 1
                    Commander.Note(self, 'cercando: atacou extratores longe da base inimiga')
                else
                    Commander.Note(self, 'atacou com ' .. count .. ' unidades')
                end
                if not Commander.Escort(self, squad, target) and not Commander.TwoFronts(self, squad, power, target, center)
                    and not Commander.Pincer(self, squad, center, target) and not Commander.Formation(self, squad, members, target, center) then
                    Commander.Command(self, squad, members, 'attack', target)
                end
            elseif water then
                -- the fleet also keeps a formation (cruisers covering, long range behind)
                if not Commander.Formation(self, squad, members, target, center) then Commander.Command(self, squad, members, 'attack', target) end
            else
                Commander.Command(self, squad, members, 'attack', target)
            end
            Log(self.brain, squad.name .. ' attacks with ' .. count .. ' units')
            return
        end
        if squad.name == 'main' then Commander.TryDrop(self, squad, power) end
    end

    -- 4. nothing worth it yet: wait at the ambush point (the drop squad holds where it landed)
    local rally
    if squad.name == 'drop' then
        rally = squad.rally or center
    else
        rally = Commander.Staging(self)
        -- an enemy army is coming: wait in front of the place it is walking to
        local pr = self.predicted
        if squad.name == 'main' and pr and t - pr.at < 45 and not water then
            rally = Toward(pr.pos, pr.from, 22)
            self.plan = 'esperando o seu ataque'
        end
        if water and not Commander.CanReach(self, members, rally, 'sea') then rally = squad.rally or center end
    end
    if squad.state ~= 'hold' or not squad.ordered or not squad.rally or Dist(squad.rally, rally) > 40 then
        squad.state = 'hold'
        squad.rally = rally
        squad.ordered = true
        Commander.Command(self, squad, members, 'attack', rally)
    end
end

-- ---------------------------------------------------------------- transports
-- targets out of reach by land (islands, plateaus): load a group, wait until it is aboard, fly,
-- unload next to the target, then fight there; the drop squad is left alone while flying
local function DropThread(self, group, transports, target, landing)
    local function aboard()
        local n = 0
        for _, u in ipairs(group) do
            local ok, a = pcall(u.IsUnitState, u, 'Attached')
            if Alive(u) and ok and a then n = n + 1 end
        end
        return n
    end
    local function alive(list)
        local out = {}
        for _, u in ipairs(list) do if Alive(u) then table.insert(out, u) end end
        return out
    end
    -- load: each transport takes its share
    local per = math.ceil(table.getn(group) / table.getn(transports))
    for i, tr in ipairs(transports) do
        local share = {}
        for j = (i - 1) * per + 1, math.min(i * per, table.getn(group)) do table.insert(share, group[j]) end
        if table.getn(share) > 0 then pcall(IssueTransportLoad, share, tr) end
    end
    local waited = 0
    while waited < 45 and aboard() < table.getn(alive(group)) do
        WaitSeconds(3)
        waited = waited + 3
    end
    local carriers = alive(transports)
    if aboard() > 0 and table.getn(carriers) > 0 then
        pcall(IssueTransportUnload, carriers, landing)
        waited = 0
        while waited < 75 and aboard() > 0 do
            WaitSeconds(3)
            waited = waited + 3
        end
    end
    -- whoever is on the ground fights; anyone still stuck goes back to the main army
    for _, u in ipairs(alive(group)) do
        u.CPDropping = nil
        local ok, a = pcall(u.IsUnitState, u, 'Attached')
        if ok and a then u.CPSquad = 'main' end
    end
    local landed = {}
    for _, u in ipairs(alive(group)) do if u.CPSquad == 'drop' then table.insert(landed, u) end end
    if table.getn(landed) > 0 then
        self.squads.drop.rally = landing
        Order(landed, 'attack', target)
    end
    for _, tr in ipairs(alive(transports)) do
        tr.CPBusy = nil
        Order({ tr }, 'move', self.home)
    end
end

function Commander.TryDrop(self, squad, power)
    local transports = {}
    for _, u in ipairs(Commander.List(self, Categories().transport)) do
        if Ready(u) and not u.CPBusy then table.insert(transports, u) end
    end
    if table.getn(transports) == 0 or not Commander.Cooldown(self, 'drop', 60) then return end
    local best, bestScore = false, 0
    for _, cell in Commander.Targets(self) do
        if not Commander.CanReach(self, squad.members, cell.pos, 'land') then
            local risk = Commander.Danger(self, cell.pos, 45)
            local score = cell.value / (1 + risk)
            if risk * self.ratio < power * 0.5 and score > bestScore then best, bestScore = cell.pos, score end
        end
    end
    if not best then return end
    local n = math.min(table.getn(squad.members), table.getn(transports) * 6)
    local group = {}
    for i = 1, n do
        local u = squad.members[i]
        if not Is(Categories().experimental, u) then
            u.CPSquad = 'drop'
            u.CPDropping = true
            table.insert(group, u)
        end
    end
    if table.getn(group) == 0 then return end
    local landing = Toward(best, self.home, 25)
    for _, tr in ipairs(transports) do tr.CPBusy = true end
    pcall(IssueClearCommands, group)
    self.squads.drop.target = best
    self.squads.drop.state = 'hold'
    self.plan = 'desembarque'
    ForkThread(DropThread, self, group, transports, best, landing)
end

-- ---------------------------------------------------------------- the guard
function Commander.LeadGuard(self, threatPos)
    local sq = self.squads.guard
    local members = sq.members
    if table.getn(members) == 0 then return end
    local M = Commander.M(self)
    local post = (M and Hottest(M.hit, self.home, 40, 100000, 1, self)) or Commander.Staging(self)
    if threatPos and Dist(threatPos, post) < 120 then
        if sq.state ~= 'defend' then
            sq.state = 'defend'
            Commander.Command(self, sq, members, 'attack', threatPos)
        end
        return
    end
    if sq.state ~= 'post' or not sq.post or Dist(sq.post, post) > 30 then
        sq.state = 'post'
        sq.post = post
        Commander.Command(self, sq, members, 'attack', post)
    end
end

-- ---------------------------------------------------------------- air force
function Commander.LeadAir(self, threatPos)
    local S = Snapshot()
    local main = self.squads.main
    local mainCenter = main.center or self.home
    local t = Now()

    -- fighters: hunt enemy aircraft when stronger, otherwise cover the army or the base
    local fighters = self.squads.fighters.members
    if table.getn(fighters) > 0 then
        local mine = AirPowerOf(fighters)
        local best, bestDist = false, 0
        local checked = 0
        for _, idx in ipairs(self.enemies) do
            for _, a in ipairs(S.armies[idx] and S.armies[idx].air or {}) do
                checked = checked + 1
                if checked > 20 then break end
                local d = math.min(Dist(a.pos, self.home), Dist(a.pos, mainCenter))
                if mine >= Commander.AntiAir(self, a.pos, 40) * 1.2 and (not best or d < bestDist) then best, bestDist = a.pos, d end
            end
        end
        local goal = best or (main.state == 'attack' and mainCenter) or threatPos or self.home
        local sq = self.squads.fighters
        if not best and main.state ~= 'attack' and not threatPos then
            -- nothing to hunt: patrol between the base and the districts (air control)
            if sq.state ~= 'patrol' then Commander.AirPatrol(self, fighters) end
            sq.goal = false
        elseif not sq.goal or Dist(sq.goal, goal) > 30 then
            sq.goal = goal
            sq.state = best and 'attack' or 'cover'
            Commander.Command(self, sq, fighters, 'attack', goal)
        end
    end

    -- bombers: weakly defended valuable targets (extractors, artillery, factories); a new target
    -- when the old one is gone, too well defended, or after a minute
    local bombers = self.squads.bombers.members
    local sq = self.squads.bombers
    if table.getn(bombers) >= 2 then
        local stillThere = false
        if sq.target then
            for _, cell in Commander.Targets(self) do
                if Dist(cell.pos, sq.target) < 20 then
                    stillThere = true
                    break
                end
            end
        end
        -- the target is gone: that was a good weak spot, come back to it later
        if sq.target and not stillThere then
            self.bombSpots = self.bombSpots or {}
            table.insert(self.bombSpots, 1, sq.target)
            while table.getn(self.bombSpots) > 4 do table.remove(self.bombSpots) end
        end
        local stale = not sq.target or not stillThere or t - (sq.since or 0) > 60
            or Commander.AntiAir(self, sq.target, 40) > AirPowerOf(fighters) + table.getn(bombers) * 2
        if stale then
            local best, bestScore = false, 0
            for _, cell in Commander.Targets(self) do
                local aa = Commander.AntiAir(self, cell.pos, 45)
                local score = (cell.value + cell.artillery * 2) / (1 + aa * 2) / (1 + Dist(self.home, cell.pos) / 600)
                -- routine: the weak spots that worked before; and the shield over the army's target
                for _, bs in (self.bombSpots or {}) do if Dist(bs, cell.pos) < 60 and aa < 2 then score = score * 2 end end
                if self.breakShield and Dist(self.breakShield, cell.pos) < 40 and table.getn(cell.shields or {}) > 0 then score = score * 3 end
                if score > bestScore then best, bestScore = cell.pos, score end
            end
            if best and bestScore > 0.4 then
                sq.state = 'attack'
                sq.target = best
                sq.since = t
                Commander.Command(self, sq, bombers, 'attack', best)
                Order(bombers, 'move', self.home, true)
            elseif sq.state ~= 'home' then
                sq.state = 'home'
                sq.target = false
                Commander.Command(self, sq, bombers, 'move', self.home)
            end
        end
    end

    -- gunships: hit the human's experimental when it can, defend, support the army's attack, or
    -- hunt where there is no anti-air
    local gunships = self.squads.gunships.members
    if table.getn(gunships) > 0 then
        local gq = self.squads.gunships
        local goal = false
        local M = Commander.M(self)
        if M and M.expPos and Commander.AntiAir(self, M.expPos, 40) < AirPowerOf(fighters) + 4 then
            goal = M.expPos
        elseif threatPos then
            goal = threatPos
        elseif main.state == 'attack' and main.target then
            goal = main.target
        else
            local best, bestScore = false, 0
            for _, cell in Commander.Targets(self) do
                if Commander.AntiAir(self, cell.pos, 45) < 2 then
                    local score = cell.value / (1 + Dist(self.home, cell.pos) / 500)
                    if score > bestScore then best, bestScore = cell.pos, score end
                end
            end
            goal = best or Commander.Staging(self)
        end
        if not gq.goal or Dist(gq.goal, goal) > 30 then
            gq.goal = goal
            Commander.Command(self, gq, gunships, 'attack', goal)
        end
    end
end

-- ---------------------------------------------------------------- scouting and counters
function Commander.Scout(self)
    local scout = self.squads.scouts.members[1] or self.squads.fighters.members[1]
    if not scout or not Commander.Cooldown(self, 'scout', 75 / Commander.Gene(self, 'scouting')) then return end
    local cells = Commander.Targets(self)
    local goal = false
    -- every other trip: the next expansion area of the map (where the enemy may be growing unseen)
    local exps = Markers().expansion
    self.scoutTrips = (self.scoutTrips or 0) + 1
    if table.getn(exps) > 0 and math.mod(self.scoutTrips, 2) == 0 then
        self.scoutIdx = math.mod(self.scoutIdx or 0, table.getn(exps)) + 1
        local m = exps[self.scoutIdx]
        goal = Point(m[1], m[3])
    elseif table.getn(cells) > 0 then
        goal = cells[Rand(1, table.getn(cells))].pos
    else
        goal = Commander.NearestEnemyStart(self)
    end
    if goal then
        Order({ scout }, 'move', goal)
        Order({ scout }, 'move', self.home, true)
    end
end

-- the match has no fog of war: the AI sees everything like everyone else
local function FullVision()
    local ok, fog = pcall(function() return ScenarioInfo.Options.FogOfWar end)
    return ok and fog == 'none'
end

-- what the enemy has, by kind: what its scouts and units have seen (like a player), or everything
-- when the map is fully visible
function Commander.Intel(self)
    if not FullVision() and self.belief then
        local b = Commander.Believed(self)
        self.intel = { air = b.air, land = b.land, naval = b.naval, towers = b.towers }
        return self.intel
    end
    local S = Snapshot()
    local intel = { air = 0, land = 0, naval = 0, towers = 0 }
    for _, idx in ipairs(self.enemies) do
        local A = S.armies[idx]
        if A then
            for _, a in ipairs(A.air) do intel.air = intel.air + a.p + a.ap * 0.5 + 1 end
            for _, m in ipairs(A.mobile) do
                if not m.air and not m.engineer then
                    if m.naval then intel.naval = intel.naval + m.p else intel.land = intel.land + m.p end
                end
            end
            for _, v in A.towers do intel.towers = intel.towers + v end
        end
    end
    self.intel = intel
    return intel
end

function Commander.Queue(self, unitId, count)
    if not unitId then return false end
    local best = false
    for _, f in ipairs(Commander.List(self, Categories().factory)) do
        if Ready(f) then
            local ok, can = pcall(f.CanBuild, f, unitId)
            if ok and can then
                local okb, busy = pcall(f.IsUnitState, f, 'Building')
                busy = okb and busy
                if not best or not busy then best = f end
                if not busy then break end
            end
        end
    end
    if not best then return false end
    return pcall(IssueBuildFactory, { best }, unitId, count)
end

function Commander.Counter(self)
    if not CFG.counter or not Commander.Cooldown(self, 'counter', 25) then return end
    local intel = Commander.Intel(self)
    if Stored(self.brain, 'MASS') < 150 then return end
    local c = Categories()
    local myAA = AirPowerOf(self.squads.fighters.members) + AirPowerOf(self.squads.main.members)
    local made = false
    local M = Commander.M(self)
    local st = M and M.style or {}
    -- what has been killing our units decides first (more than 6 losses of one kind)
    local lb = self.lossBy
    if lb.air >= 6 and lb.air >= lb.towers and lb.air >= lb.land then
        made = Commander.Queue(self, self.units.fighter, 4) or Commander.Queue(self, self.units.aaLand, 4)
        if made then self.plan = 'perdendo para a aviacao: antiaereo' Commander.Note(self, 'perdia unidades para a aviacao: fez antiaereo') end
    elseif lb.towers >= 6 and lb.towers >= lb.land then
        made = Commander.Queue(self, self.units.arty, 3)
        if made then self.plan = 'perdendo para as torres: artilharia' Commander.Note(self, 'perdia unidades para as torres: fez artilharia') end
    end
    if made then return end
    -- an air player: anti-air before the bombers arrive
    local airLimit = 6
    if (st.air or 0) > 0.4 then airLimit = 2 end
    -- an experimental appeared: bombers
    if M and M.expPos and (st.tech or 0) > 0.3 then
        made = Commander.Queue(self, self.units.bomber, 2)
        if made then self.plan = 'contra o experimental' end
    end
    local airN = math.max(2, math.floor(3 * Commander.Gene(self, 'air') + 0.5))
    if not made and intel.air > airLimit / Commander.Gene(self, 'air') and myAA < intel.air * ((st.air or 0) > 0.4 and 1.1 or 0.8) * Commander.Gene(self, 'air') then
        made = Commander.Queue(self, self.units.fighter, airN) or Commander.Queue(self, self.units.aaLand, airN)
        if made then self.plan = 'contra-ataque aereo' end
    end
    if not made and (intel.towers > 40 or (st.turtle or 0) > 0.5) then
        local arty = 0
        for _, u in ipairs(self.squads.main.members) do if Is(c.indirect, u) then arty = arty + 1 end end
        local want = 4
        if (st.turtle or 0) > 0.5 then want = 8 end
        if arty < want then
            made = Commander.Queue(self, self.units.arty, 2)
            if made then self.plan = 'artilharia contra defesas' end
        end
    end
    if not made and (intel.naval > 10 / Commander.Gene(self, 'naval') or (st.naval or 0) > 0.5) and PowerOf(self.squads.fleet.members) < math.max(intel.naval, 10) * Commander.Gene(self, 'naval') then
        made = Commander.Queue(self, self.units.ship, 2)
        if made then self.plan = 'reforco naval' end
    end
    if not made and (st.turtle or 0) > 0.5 and Commander.Cooldown(self, 'turtlebombers', 90) then
        -- a turtle player: bombers over the defences
        made = Commander.Queue(self, self.units.bomber, 2)
        if made then self.plan = 'bombardeiros contra a fortaleza' end
    end
    if not made and intel.land > PowerOf(self.squads.main.members) * 1.5 then
        made = Commander.Queue(self, self.units.tank, 3)
        if made then self.plan = 'reforco de terra' end
    end
end

-- ---------------------------------------------------------------- bases
-- an idle engineer first; only urgent jobs take one that is busy (but never one that is building)
function Commander.Engineer(self, near, urgent)
    local best, bestD, busyBest, busyD = false, 0, false, 0
    for _, e in ipairs(Commander.List(self, Categories().engineer)) do
        if Ready(e) then
            local okb, building = pcall(e.IsUnitState, e, 'Building')
            if not (okb and building) then
                local d = Dist(e:GetPosition(), near)
                if d < 400 then
                    local oki, idle = pcall(e.IsIdleState, e)
                    if oki and idle then
                        if not best or d < bestD then best, bestD = e, d end
                    elseif not busyBest or d < busyD then
                        busyBest, busyD = e, d
                    end
                end
            end
        end
    end
    if best then return best end
    if urgent then return busyBest end
    return false
end

function Commander.Site(self, unitId, near)
    for ring = 0, 4 do
        for step = 0, 7 do
            local a = step * 0.785 + ring * 0.4
            local r = 6 + ring * 6
            local x, z = near[1] + math.cos(a) * r, near[3] + math.sin(a) * r
            local ok, can = pcall(self.brain.CanBuildStructureAt, self.brain, unitId, { x, 0, z })
            if ok and can then return x, z end
        end
    end
    return false
end

function Commander.Build(self, unitId, near, urgent, eng)
    if not unitId then return false end
    eng = eng or Commander.Engineer(self, near, urgent)
    if not eng then return false end
    local x, z = Commander.Site(self, unitId, near)
    if not x then return false end
    pcall(IssueClearCommands, { eng })
    return pcall(self.brain.BuildStructure, self.brain, eng, unitId, { x, z, 0 }, false)
end

-- towers where expansions are attacked or where the human usually strikes; a forward outpost
-- and a protected economic base
function Commander.Bases(self, clusters, threatKey)
    if not CFG.build then return end
    local mass = Stored(self.brain, 'MASS')
    local M = Commander.M(self)
    if M and mass >= 250 and Commander.Cooldown(self, 'foresight', 90) then
        local st = M.style
        local id = self.units.tower
        if (st.air or 0) > 0.5 then id = self.units.aatower end
        -- a rush is expected: towers at home facing the route the human uses
        if (st.rush or 0) > 0.5 and Now() < 600 then
            local enemy = Commander.NearestEnemyStart(self)
            local spot = Hottest(M.route, self.home, 40, 260, 0.5) or (enemy and Toward(self.home, enemy, 30))
            if spot and Commander.Build(self, self.units.tower, Toward(self.home, spot, 28)) then
                self.plan = 'preparando contra o rush'
                return
            end
        end
        -- the places the human keeps hitting get a tower before the next attack
        local hot = Hottest(M.hit, self.home, 0, 100000, 2, self)
        if hot then
            local towers = SumAround(Snapshot(), { self.army }, 'towers', hot, 30)
            if towers < 8 and Commander.Build(self, id, hot) then
                self.plan = 'fortificando onde voce ataca'
                return
            end
        end
    end
    local towersGene = self.P.towers * Commander.Gene(self, 'defense')
    if threatKey and clusters[threatKey] and mass >= 200 / towersGene and Commander.Cooldown(self, 'tower', 40 / towersGene) then
        local cl = clusters[threatKey]
        local airUnits = 0
        local S = Snapshot()
        for _, idx in ipairs(self.enemies) do
            for _, a in ipairs(S.armies[idx] and S.armies[idx].air or {}) do
                if Dist(a.pos, cl.pos) < 60 then airUnits = airUnits + 1 end
            end
        end
        local id = self.units.tower
        if airUnits >= 3 then id = self.units.aatower end
        if Commander.Build(self, id, Toward(cl.pos, self.home, 8), true) then self.plan = 'defendendo expansao' end
    end
    if Now() < 300 or mass < 400 or not Commander.Cooldown(self, 'outpost', 60) then return end
    local enemy = Commander.NearestEnemyStart(self)
    if not enemy then return end
    local forward, forwardD, eco, ecoD = false, 0, false, 0
    for key, cl in clusters do
        if Dist(cl.pos, self.home) > 80 then
            local d = Dist(cl.pos, enemy)
            if not forward or d < forwardD then forward, forwardD = cl, d end
            if cl.extractors >= 2 and (not eco or d > ecoD) then eco, ecoD = cl, d end
        end
    end
    -- forward outpost: a factory near the front for quick reinforcements
    if forward and forward.factories == 0 and not self.built['f' .. forward.key] then
        if Commander.Build(self, self.units.factory, forward.pos) then
            self.built['f' .. forward.key] = true
            self.plan = 'posto avancado'
            return
        end
    end
    -- economic base: a shield over the safest extractor field
    if eco and not self.built['e' .. eco.key] then
        if Commander.Build(self, self.units.shield, eco.pos) then
            self.built['e' .. eco.key] = true
            self.plan = 'protegendo base economica'
        end
    end
end

-- ---------------------------------------------------------------- districts
-- The game packs the main base into one square. The commander plans districts around it, on good
-- ground: flat and dry, inside its own territory (closer to its home than to anyone else's, and
-- away from the districts of allied AIs), spaced out, on land it is not using yet, preferring the
-- places that held in earlier matches on this map and avoiding the ones that fell. Each district
-- has a job: bastions face the enemy on the narrow passages and the high ground (with a line of
-- towers across the passage when it is narrow), workshops on the flanks make units near the front
-- lines, the rear keeps energy, research and radar away from the fighting, a forge builds
-- experimentals behind shields, harbors put shipyards on the coast. Every building gets its own
-- plot (streets between them), towers in front and the rest behind. A few engineers of its own do
-- the work (one can fly to an island to start a district there); fallen districts are rebuilt.

-- what each district builds, in order: { unit, ahead, sideways } (offsets in map units, turned
-- so "ahead" points at the enemy; for harbors, at the water)
local DISTRICT_PLANS = {
    bastion = {
        { 'tower', 18, -12 }, { 'tower', 18, 12 }, { 'shield', 0, 0 }, { 'aatower', 6, 22 },
        { 'factory', -24, 0 }, { 'tower', 24, 0 }, { 'radar', -14, 26 }, { 'artillery', -6, -22 }, { 'energy', -24, 24 }, { 'aatower', 6, -24 },
    },
    workshop = {
        { 'factory', 0, 0 }, { 'tower', 22, 0 }, { 'energy', -18, 18 }, { 'airfactory', 0, -26 },
        { 'shield', -12, 8 }, { 'aatower', 16, -18 }, { 'energy', -18, -18 }, { 'tower', 20, 20 },
    },
    rear = {
        { 'energy', 0, 0 }, { 'research', -20, 0 }, { 'aatower', 14, 10 }, { 'shield', 0, 16 },
        { 'energy', 0, -18 }, { 'radar', -18, 20 }, { 'tower', 18, -14 },
    },
    -- second line between a bastion and the main base (defense in depth)
    inner = { { 'tower', 10, -10 }, { 'tower', 10, 10 }, { 'aatower', 0, 0 }, { 'shield', -10, 0 } },
    forge = {
        { 'shield', 0, 0 }, { 'aatower', 12, 14 }, { 'expfactory', -6, -20 }, { 'shield', -16, -6 },
        { 'aatower', 12, -16 }, { 'tower', 24, 0 }, { 'shield', 6, 12 },
    },
    harbor = {
        { 'navalfactory', 24, 0 }, { 'tower', 0, -16 }, { 'aatower', 0, 16 }, { 'shield', -10, 0 },
        { 'navalfactory', 26, 26 }, { 'tower', 12, 28 },
    },
}
-- a narrow passage in front of a bastion gets a line of towers across it
local CHOKE_LINE = { { 'tower', 34, -18 }, { 'tower', 36, 0 }, { 'tower', 34, 18 } }
local ROLE_LABEL = { bastion = 'bastiao', workshop = 'oficina', rear = 'retaguarda', forge = 'forja', harbor = 'porto', inner = 'segunda linha' }
local COMPASS = { 'leste', 'sudeste', 'sul', 'sudoeste', 'oeste', 'noroeste', 'norte', 'nordeste' }

local function MapSize()
    local ok, w, h = pcall(function() return ScenarioInfo.size[1], ScenarioInfo.size[2] end)
    if ok and w and h then return w, h end
    return 1024, 1024
end

local function Clock(t)
    return math.floor(t / 60) .. ':' .. string.format('%02d', math.floor(math.mod(t, 60)))
end

-- how uneven the ground is around a point (0 = flat); water counts as unusable
local function Roughness(x, z, r)
    if IsWater(x, z) then return 999 end
    local h0, worst = Height(x, z), 0
    for ring = 1, 2 do
        for i = 0, 7 do
            local a = i * 0.785 + ring * 0.39
            local px, pz = x + math.cos(a) * r * ring / 2, z + math.sin(a) * r * ring / 2
            if IsWater(px, pz) then return 999 end
            local d = math.abs(Height(px, pz) - h0)
            if d > worst then worst = d end
        end
    end
    return worst
end

-- the direction of open water next to a dry point (for harbors), or false
local function WaterSide(x, z)
    for _, r in { 28, 40 } do
        for i = 0, 7 do
            local a = i * 0.785
            local dx, dz = math.cos(a), math.sin(a)
            if IsWater(x + dx * r, z + dz * r) and IsWater(x + dx * (r + 14), z + dz * (r + 14)) then return dx, dz end
        end
    end
    return false
end

-- what the AI did, for the panel (newest first, with the game clock)
function Commander.Note(self, text)
    local j = self.journal
    if j[1] and j[1].text == text then return end
    table.insert(j, 1, { t = Clock(Now()), text = text })
    while table.getn(j) > 10 do table.remove(j) end
end

-- start positions of every other army (allies too: their land is theirs)
function Commander.OtherHomes(self, enemiesOnly)
    local out = {}
    for _, b in ArmyBrains do
        local ok, idx = pcall(b.GetArmyIndex, b)
        if ok and idx ~= self.army and not Civilian(idx) and not Defeated(b) and (not enemiesOnly or Enemy(self.army, idx)) then
            local ok2, x, z = pcall(b.GetArmyStartPos, b)
            if ok2 and x then table.insert(out, Point(x, z)) end
        end
    end
    return out
end

function Commander.EnemyHomes(self)
    if not self.memo.enemyHomes then self.memo.enemyHomes = Commander.OtherHomes(self, true) end
    return self.memo.enemyHomes
end

-- the buildings of a district: its plan plus the tower line when it guards a narrow passage
local function PlanOf(d)
    if d.items then return d.items end
    local list = {}
    for _, it in ipairs(DISTRICT_PLANS[d.role] or {}) do table.insert(list, it) end
    if d.choke then
        for i, it in ipairs(CHOKE_LINE) do table.insert(list, 2 + i, it) end
    end
    d.items = list
    return list
end

-- the memory of this map: districts that held (+) and fell (-) in earlier matches
local function MapMemory(key)
    local M = CPAI.model
    if not M then return 0 end
    return math.min(3, (M.held and M.held[key] or 0) * 0.15) - math.min(4, (M.lost and M.lost[key] or 0) * 0.4)
end

local function RememberPlace(kind, pos, amount)
    local M = Model()
    M[kind] = M[kind] or {}
    local key = CellKey(pos)
    M[kind][key] = math.min(20, (M[kind][key] or 0) + amount)
end

-- picks the district sites (keeps the ones already planned, adds new ones)
function Commander.PlanDistricts(self)
    local W, H = MapSize()
    local home = self.home
    local scale = math.max(0.6, math.min(1.6, math.min(W, H) / 1024))
    local others = Commander.OtherHomes(self)
    local enemy = Commander.NearestEnemyStart(self)
    local fx, fz = 1, 0
    if enemy then
        local d = math.max(1, Dist(home, enemy))
        fx, fz = (enemy[1] - home[1]) / d, (enemy[3] - home[3]) / d
    end
    local S = Snapshot()
    local mine = S.armies[self.army] and S.armies[self.army].structs or {}
    local districts = self.districts or {}
    local hard = self.difficulty >= 3 or CFG.level >= 2
    local want = (hard and 10 or 7) + math.floor((Commander.Gene(self, 'expansion') - 1) * 4 + 0.5)
    local planned = 0
    for _, d in districts do if d.role ~= 'inner' then planned = planned + 1 end end
    if planned >= want then return districts end
    -- districts of allied AIs: their land
    local claimed = {}
    for _, ally in Commander.Allies(self) do
        for _, d in (ally.districts or {}) do table.insert(claimed, d.pos) end
    end
    local function free(p, gap)
        for _, d in districts do if Dist(d.pos, p) < gap then return false end end
        for _, q in claimed do if Dist(q, p) < gap then return false end end
        return true
    end
    local function own(p, r)
        if r < 80 * scale then return false end
        for _, o in others do
            if Dist(p, o) < Dist(p, home) * 1.25 then return false end
        end
        return true
    end
    local cands, harbors = {}, {}
    local naval = self.units.navalfactory
    for _, ring in { 105, 150, 200 } do
        local r = ring * scale
        for step = 0, 17 do
            local a = step * 0.349 + ring * 0.01
            local x, z = home[1] + math.cos(a) * r, home[3] + math.sin(a) * r
            if x > 32 and z > 32 and x < W - 32 and z < H - 32 then
                local p = Point(x, z)
                local mineHere = own(p, r)
                local rough = mineHere and Roughness(x, z, 22 * scale) or 999
                local dx, dz = (x - home[1]) / r, (z - home[3]) / r
                local key = CellKey(p)
                if rough < 7 then
                    local facing = dx * fx + dz * fz
                    local role = 'workshop'
                    if facing > 0.45 then role = 'bastion' elseif facing < -0.35 then role = 'rear' end
                    -- land it is not using yet
                    local used = 0
                    for _, st in ipairs(mine) do
                        if Dist(st.pos, p) < 40 then used = used + 1 end
                    end
                    local score = 2 - rough * 0.12 - used * 0.35 - (ring - 105) / 300 + MapMemory(key)
                    local corridor = 120
                    if role == 'bastion' then
                        -- a narrow way toward the enemy and high ground make a good wall
                        corridor = Corridor(p, fx, fz)
                        score = score + (120 - corridor) / 120 * 0.9 + math.max(-0.5, math.min(1, HighGround(p) / 8)) * 0.6
                    end
                    for _, m in Markers().expansion do
                        if Dist(m, p) < 70 then score = score + 0.5 end
                    end
                    for _, m in Markers().defensive do
                        if Dist(m, p) < 50 and role == 'bastion' then score = score + 0.4 end
                    end
                    table.insert(cands, { pos = p, role = role, score = score, angle = (math.atan2 or math.atan)(dz, dx), choke = corridor < 70 })
                elseif naval and mineHere and not IsWater(x, z) then
                    -- the coast: a harbor needs dry ground next to open water
                    local wx, wz = WaterSide(x, z)
                    if wx then
                        table.insert(harbors, { pos = p, role = 'harbor', score = 1 + MapMemory(key) - (ring - 105) / 300, angle = (math.atan2 or math.atan)(dz, dx), wx = wx, wz = wz })
                    end
                end
            end
        end
    end
    table.sort(cands, function(a, b) return a.score > b.score end)
    table.sort(harbors, function(a, b) return a.score > b.score end)
    local roles = { bastion = 0, workshop = 0, rear = 0, forge = 0, harbor = 0, inner = 0 }
    for _, d in districts do roles[d.role] = (roles[d.role] or 0) + 1 end
    local limit = { bastion = hard and 4 or 3, workshop = hard and 3 or 2, rear = 1, forge = 1, harbor = hard and 2 or 1 }
    local function add(c, role)
        local k = math.mod(math.floor((c.angle + 3.1416 + 0.3927) / 0.7854), 8) + 1
        roles[role] = roles[role] + 1
        local d = { pos = c.pos, role = role, step = 1, tries = 0, fx = c.wx or fx, fz = c.wz or fz, choke = c.choke,
            name = ROLE_LABEL[role] .. ' ' .. COMPASS[k] }
        table.insert(districts, d)
    end
    local gap = 85 * scale
    -- the second place behind the base becomes the forge (experimentals far from the front)
    local function roleOf(c)
        if c.role == 'rear' and roles.rear >= limit.rear then return 'forge' end
        return c.role
    end
    -- first one of each job (the best place for it), then the rest by score
    for _, c in harbors do
        if roles.harbor >= 1 then break end
        if free(c.pos, gap) then add(c, 'harbor') end
    end
    for _, job in { 'bastion', 'workshop', 'rear', 'forge' } do
        for _, c in cands do
            if table.getn(districts) >= want or (roles[job] or 0) >= 1 then break end
            if roleOf(c) == job and free(c.pos, gap) then add(c, job) end
        end
    end
    for _, c in harbors do
        if roles.harbor >= limit.harbor or table.getn(districts) >= want then break end
        if free(c.pos, gap) then add(c, 'harbor') end
    end
    for _, c in cands do
        if table.getn(districts) >= want then break end
        local role = roleOf(c)
        if roles[role] < limit[role] and free(c.pos, gap) then add(c, role) end
    end
    -- a second line of towers between each bastion and home (defense in depth)
    for _, b in districts do
        if b.role == 'bastion' and not b.inner and not b.island then
            local p = Toward(home, b.pos, Dist(home, b.pos) * 0.55)
            local ok = not IsWater(p[1], p[3])
            for _, d in districts do if d ~= b and Dist(d.pos, p) < 40 then ok = false end end
            if ok then
                b.inner = true
                table.insert(districts, { pos = p, role = 'inner', step = 1, tries = 0, fx = b.fx, fz = b.fz, name = 'segunda linha ' .. string.sub(b.name, 9) })
            end
        end
    end
    -- bastions first (they protect the rest), then workshops, harbors, the rear and the forge
    local order = { bastion = 1, inner = 2, workshop = 3, harbor = 4, rear = 5, forge = 6 }
    table.sort(districts, function(a, b)
        if order[a.role] ~= order[b.role] then return order[a.role] < order[b.role] end
        if a.island ~= b.island then return not a.island end
        return Dist(a.pos, home) < Dist(b.pos, home)
    end)
    self.districts = districts
    return districts
end

-- the commander's own builders: idle engineers taken out of the game's pool (a few)
function Commander.Builders(self, want)
    local c = Categories()
    local list, free = {}, {}
    for _, e in ipairs(Commander.List(self, c.engineer)) do
        if Ready(e) then
            if e.CPBuilder then table.insert(list, e) else table.insert(free, e) end
        end
    end
    local taken = {}
    for _, e in ipairs(free) do
        if table.getn(list) >= want then break end
        local ok, idle = pcall(e.IsIdleState, e)
        if ok and idle then
            e.CPBuilder = true
            table.insert(list, e)
            table.insert(taken, e)
        end
    end
    if table.getn(taken) > 0 then
        if not self.builderPlatoon then
            local ok, p = pcall(self.brain.MakePlatoon, self.brain, '', '')
            self.builderPlatoon = ok and p or false
        end
        if self.builderPlatoon then pcall(self.brain.AssignUnitsToPlatoon, self.brain, self.builderPlatoon, taken, 'Support', 'None') end
    end
    -- not enough: the factories make more (one at a time)
    if table.getn(list) < want and self.units.engineer and Commander.Cooldown(self, 'builder', 40) then
        Commander.Queue(self, self.units.engineer, 1)
    end
    return list
end

-- how many of our buildings stand around a district
local function Standing(self, pos, radius)
    local S = Snapshot()
    local n = 0
    for _, st in ipairs(S.armies[self.army] and S.armies[self.army].structs or {}) do
        if Dist(st.pos, pos) < radius then n = n + 1 end
    end
    return n
end

-- finished districts that were wiped out are rebuilt (and remembered as a bad place); the ones
-- still standing are remembered as good places for this map
function Commander.CheckDistricts(self)
    if not Commander.Cooldown(self, 'districtcheck', 45) then return end
    for _, d in (self.districts or {}) do
        local n = table.getn(PlanOf(d))
        if d.step > n then
            local standing = Standing(self, d.pos, 45)
            if standing < math.max(1, math.floor(n * 0.35)) then
                if Commander.MobileDanger(self, d.pos, 70) < 3 and (d.rebuilds or 0) < 3 then
                    d.rebuilds = (d.rebuilds or 0) + 1
                    d.step, d.tries, d.done = 1, 0, false
                    self.tally.lost = self.tally.lost + 1
                    RememberPlace('lost', d.pos, 1)
                    Commander.Note(self, 'bairro ' .. d.name .. ' caiu: reconstruindo')
                end
            else
                RememberPlace('held', d.pos, 0.25)
            end
        end
    end
end

function Commander.Districts(self, threatPos)
    if not CFG.build then return end
    local t = Now()
    local start = Commander.Strategy(self, 'fastland') and 100 or 150
    if t < start then return end
    if not self.districts or Commander.Cooldown(self, 'plan', 150) then Commander.PlanDistricts(self) end
    local districts = self.districts or {}
    if table.getn(districts) == 0 then return end
    Commander.CheckDistricts(self)
    local hard = self.difficulty >= 3 or CFG.level >= 2
    -- one more district open every 1.5 to 2 minutes
    local open = math.min(table.getn(districts), 1 + math.floor((t - 150) / ((hard and 80 or 120) / Commander.Gene(self, 'expansion'))))
    local builders = Commander.Builders(self, (hard and 4 or 2) + ((Commander.Strategy(self, 'fastland') or Commander.Strategy(self, 'territory')) and 1 or 0))
    if table.getn(builders) == 0 then return end
    if Stored(self.brain, 'MASS') < 120 then return end
    -- each idle builder takes the next building of the least finished open district it can reach
    for _, eng in ipairs(builders) do
        local okb, building = pcall(eng.IsUnitState, eng, 'Building')
        local oki, idle = pcall(eng.IsIdleState, eng)
        local ep = eng:GetPosition()
        if not (okb and building) and oki and idle and not eng.CPFlying then
            local pick = false
            for i = 1, table.getn(districts) do
                local d = districts[i]
                local plan = PlanOf(d)
                -- districts open one by one (an island one as soon as its engineer lands)
                local isOpen = i <= open or d.island
                -- an engineer flown to an island only builds there (and only it builds there)
                local here = (d.island and eng.CPIsland == d.name) or (not d.island and not eng.CPIsland)
                local ready = d.role ~= 'forge' or t >= 600 / Commander.Gene(self, 'tech') or self.forgeNow
                if isOpen and here and ready and d.step <= table.getn(plan) and d.tries < 6 and (not threatPos or Dist(threatPos, d.pos) > 90)
                    and Commander.MobileDanger(self, d.pos, 60) < 3 then
                    if not pick or d.step < pick.step then pick = d end
                end
            end
            if pick then
                local plan = PlanOf(pick)
                local item = plan[pick.step]
                local id = self.units[item[1]]
                if not id then
                    pick.step = pick.step + 1
                else
                    -- the plot: "ahead" toward the enemy (or the water), "sideways" across
                    local x = pick.pos[1] + pick.fx * item[2] - pick.fz * item[3]
                    local z = pick.pos[3] + pick.fz * item[2] + pick.fx * item[3]
                    local plot = Point(x, z)
                    -- long range artillery goes to the highest ground around its plot
                    if item[1] == 'artillery' then local ok, hs = pcall(HighSpot, plot) if ok and hs then plot = hs end end
                    if Commander.Build(self, id, plot, false, eng) then
                        pick.step = pick.step + 1
                        pick.tries = 0
                        self.plan = 'construindo o bairro ' .. pick.name
                        if pick.step == 2 then Commander.Note(self, 'comecou o bairro ' .. pick.name) end
                    else
                        -- no room there: try the next building next time (and give up on a bad site)
                        pick.tries = pick.tries + 1
                        if pick.tries >= 3 then pick.step = pick.step + 1 end
                    end
                end
                if pick.step > table.getn(plan) and not pick.done then
                    pick.done = true
                    self.tally.districts = self.tally.districts + 1
                    Commander.Note(self, 'bairro ' .. pick.name .. ' pronto')
                end
            end
        end
    end
    Commander.IslandHop(self, builders)
end

-- an island near home that the engineers cannot walk to: one flies there and starts a district
local function IslandThread(self, eng, tr, landing, d)
    pcall(IssueClearCommands, { eng })
    pcall(IssueTransportLoad, { eng }, tr)
    local waited = 0
    local function aboard() local ok, a = pcall(eng.IsUnitState, eng, 'Attached') return ok and a end
    while waited < 40 and Alive(eng) and not aboard() do WaitSeconds(2) waited = waited + 2 end
    if Alive(eng) and aboard() and Alive(tr) then
        pcall(IssueTransportUnload, { tr }, landing)
        waited = 0
        while waited < 60 and Alive(eng) and aboard() do WaitSeconds(2) waited = waited + 2 end
    end
    eng.CPFlying = nil
    if Alive(eng) and not aboard() and Dist(eng:GetPosition(), landing) < 60 then
        eng.CPIsland = d.name
        table.insert(self.districts, d)
        Commander.Note(self, 'engenheiro levado de aviao para a ilha: bairro ' .. d.name)
    end
    tr.CPBusy = nil
    if Alive(tr) then Order({ tr }, 'move', self.home) end
end

function Commander.IslandHop(self, builders)
    if Now() < 420 or table.getn(builders) < 2 or not Commander.Cooldown(self, 'island', 120) then return end
    for _, d in (self.districts or {}) do if d.island then return end end
    local tr = false
    for _, u in ipairs(Commander.List(self, Categories().transport)) do
        if Ready(u) and not u.CPBusy then tr = u break end
    end
    if not tr then
        if self.units.transport then Commander.Queue(self, self.units.transport, 1) end
        return
    end
    local enemies = Commander.OtherHomes(self, true)
    local best, bestD = false, 0
    for _, m in Markers().expansion do
        local d = Dist(m, self.home)
        local mine = d < 450
        for _, e in enemies do if Dist(m, e) < d * 1.2 then mine = false end end
        if mine and (not best or d < bestD) and Commander.Danger(self, m, 50) < 2
            and not Commander.CanReach(self, { builders[1] }, m, 'land') then
            best, bestD = m, d
        end
    end
    if not best then return end
    local eng = builders[table.getn(builders)]
    eng.CPFlying = true
    tr.CPBusy = true
    local d = { pos = Point(best[1], best[3]), role = 'workshop', step = 1, tries = 0, island = true,
        fx = 1, fz = 0, name = 'ilha ' .. Clock(Now()) }
    local enemy = Commander.NearestEnemyStart(self)
    if enemy then
        local dd = math.max(1, Dist(d.pos, enemy))
        d.fx, d.fz = (enemy[1] - d.pos[1]) / dd, (enemy[3] - d.pos[3]) / dd
    end
    self.plan = 'levando engenheiro para a ilha'
    ForkThread(IslandThread, self, eng, tr, Toward(d.pos, self.home, 10), d)
end

-- ---------------------------------------------------------------- the main base and the economy
-- shields over the factory blocks (two layers over the big ones), anti-air between the districts,
-- more factories when mass piles up and generators when energy runs short
function Commander.BaseShields(self)
    if not CFG.build or Now() < 240 or not self.units.shield or not Commander.Cooldown(self, 'shields', 60) then return end
    if Stored(self.brain, 'MASS') < 250 then return end
    local S = Snapshot()
    local mine = S.armies[self.army] and S.armies[self.army].structs or {}
    for _, cl in (self.lastClusters or {}) do
        if cl.factories >= 2 and Dist(cl.pos, self.home) < 200 then
            local shields = 0
            for _, st in ipairs(mine) do
                if st.kind == 'shield' and Dist(st.pos, cl.pos) < 35 then shields = shields + 1 end
            end
            local want = cl.factories >= 4 and 2 or 1
            if shields < want and Commander.Build(self, self.units.shield, cl.pos) then
                Commander.Note(self, shields == 0 and 'escudo sobre as fabricas' or 'segunda camada de escudo sobre as fabricas')
                return
            end
        end
    end
end

function Commander.AirNet(self)
    if not CFG.build or not self.units.aatower or not Commander.Cooldown(self, 'airnet', 75) then return end
    local intel = self.intel or {}
    if (intel.air or 0) < 6 or Stored(self.brain, 'MASS') < 200 then return end
    local S = Snapshot()
    local spots = { self.home }
    for _, d in (self.districts or {}) do
        if d.step > 2 and not d.island then table.insert(spots, d.pos) end
    end
    -- the place between two of our spots with the least anti-air
    local worst, worstAA = false, 4
    for i, a in ipairs(spots) do
        for j = i + 1, table.getn(spots) do
            local b = spots[j]
            if Dist(a, b) < 260 then
                local mid = Point((a[1] + b[1]) / 2, (a[3] + b[3]) / 2)
                local aa = SumAround(S, { self.army }, 'aa', mid, 45)
                if not IsWater(mid[1], mid[3]) and aa < worstAA then worst, worstAA = mid, aa end
            end
        end
    end
    if worst and Commander.Build(self, self.units.aatower, worst) then
        Commander.Note(self, 'rede antiaerea entre os bairros')
    end
end

function Commander.Economy(self)
    if not CFG.build or Now() < 300 or not Commander.Cooldown(self, 'economy', 45) then return end
    local mass = Stored(self.brain, 'MASS')
    local energy = Stored(self.brain, 'ENERGY')
    local enemy = Commander.NearestEnemyStart(self)
    local behind = enemy and Toward(self.home, enemy, -35) or self.home
    if energy < 150 and self.units.energy and mass >= 100 then
        if Commander.Build(self, self.units.energy, behind) then Commander.Note(self, 'faltou energia: mais geradores') end
        return
    end
    if mass > 1200 then
        -- mass piling up: one more factory, in a workshop if there is one
        local spot = false
        for _, d in (self.districts or {}) do
            if d.role == 'workshop' and d.step > 2 and not d.island then spot = d.pos break end
        end
        local id = self.units.factory
        if (self.intel.air or 0) > (self.intel.land or 0) and self.units.airfactory then id = self.units.airfactory end
        if Commander.Build(self, id, spot or (enemy and Toward(self.home, enemy, 40)) or self.home) then
            Commander.Note(self, 'massa sobrando: mais uma fabrica')
        end
    end
end

-- ---------------------------------------------------------------- reading the enemy
-- an enemy army massing and walking toward our places: the army waits where it is going to hit
function Commander.Foresee(self)
    local S = Snapshot()
    local t = Now()
    local cells = {}
    for _, idx in ipairs(self.enemies) do
        for _, m in ipairs(S.armies[idx] and S.armies[idx].mobile or {}) do
            if not m.air and not m.engineer and not m.naval then
                local key = CellKey(m.pos)
                local c = cells[key]
                if not c then c = { pos = m.pos, power = 0 } cells[key] = c end
                c.power = c.power + m.p
            end
        end
    end
    -- the strongest group (neighbouring cells count together)
    local best, bestP = false, 0
    for _, c in cells do
        local p = 0
        for _, o in cells do if Dist(o.pos, c.pos) < 75 then p = p + o.power end end
        if p > bestP then best, bestP = c, p end
    end
    local mainP = PowerOf(self.squads.main.members)
    if not best or bestP < math.max(6, mainP * 0.4) then
        self.watch = false
        return
    end
    -- our nearest place to that group
    local spots = { self.home }
    for _, cl in (self.lastClusters or {}) do table.insert(spots, cl.pos) end
    for _, d in (self.districts or {}) do if d.step > 1 then table.insert(spots, d.pos) end end
    local near, nearD = self.home, Dist(best.pos, self.home)
    for _, p in spots do
        local d = Dist(best.pos, p)
        if d < nearD then near, nearD = p, d end
    end
    local w = self.watch
    if w and t - w.t >= 6 and nearD < 300 and w.d - nearD >= 20 and Dist(w.target, near) < 80 then
        if not self.predicted or Dist(self.predicted.pos, near) > 40 then
            Commander.Note(self, 'viu um exercito vindo: esperando na frente dele')
        end
        self.predicted = { pos = near, from = best.pos, at = t, power = bestP }
    end
    if not w or t - w.t >= 6 then self.watch = { d = nearD, t = t, target = near } end
end

-- humans on our side attacking: we hit the same place
function Commander.HumanPush(self)
    self.joinPos = false
    local S = Snapshot()
    for idx, A in S.armies do
        if A.human and Allied(self.army, idx) then
            local cells = {}
            for _, m in ipairs(A.mobile) do
                if not m.air and not m.engineer then
                    local key = CellKey(m.pos)
                    local c = cells[key]
                    if not c then c = { pos = m.pos, power = 0 } cells[key] = c end
                    c.power = c.power + m.p
                end
            end
            for _, cell in Commander.Targets(self) do
                local p = 0
                for _, c in cells do if Dist(c.pos, cell.pos) < 70 then p = p + c.power end end
                if p >= 6 then
                    if not self.joinPos then Commander.Note(self, 'atacando junto com o aliado humano') end
                    self.joinPos = cell.pos
                    self.joinPower = p
                    return
                end
            end
        end
    end
end

-- ---------------------------------------------------------------- research and repairs
-- research follows the player: anti-air upgrades against an air player, shields against
-- artillery and bombers, long range artillery against a turtle, anti-nukes against nukes
function Commander.Research(self)
    if not Commander.Cooldown(self, 'research', 45) then return end
    local M = Commander.M(self)
    local sys = self.brain.SkirmishAISystem
    if not sys or not M then return end
    local st = M.style
    local function need(name, why)
        if self.needs[name] then return end
        if pcall(sys.ResearchNeed, sys, name) then
            self.needs[name] = true
            self.plan = why
        end
    end
    if (st.air or 0) > 0.4 then need('NeedAAUpgrade', 'pesquisando antiaereo') end
    if (M.shares.arty or 0) > 0.2 or (st.air or 0) > 0.5 then need('NeedShields', 'pesquisando escudos') end
    if (st.turtle or 0) > 0.5 then need('NeedArtillery', 'pesquisando artilharia de longo alcance') end
    if M.nukes then need('NeedAntiNukes', 'pesquisando defesa antimissil') end
    if Stored(self.brain, 'MASS') < 20 and (self.extractors or 0) >= 8 and Now() > 900 then
        need('NeedMassConv', 'pesquisando conversor de massa')
    end
end

-- after a fight, a free engineer repairs the most damaged building nearby
function Commander.Repair(self, threatPos)
    if threatPos or not Commander.Cooldown(self, 'repair', 30) then return end
    local S = Snapshot()
    local A = S.armies[self.army]
    local worst, worstF = false, 0.7
    for _, s in ipairs(A and A.structs or {}) do
        if Dist(s.pos, self.home) < 200 and Alive(s.u) then
            local f = HealthFraction(s.u)
            if f < worstF then worst, worstF = s.u, f end
        end
    end
    if not worst then return end
    local eng = Commander.Engineer(self, worst:GetPosition(), false)
    if eng then
        pcall(IssueClearCommands, { eng })
        pcall(IssueRepair, { eng }, worst)
    end
end

-- ---------------------------------------------------------------- the ACU
function Commander.LeadAcu(self, threatPos, threatPower)
    local acu = Commander.List(self, Categories().acu)[1]
    if not acu or not Ready(acu) then return end
    local f = HealthFraction(acu)
    local pos = acu:GetPosition()
    local danger = Commander.MobileDanger(self, pos, 40) + SumAround(Snapshot(), self.enemies, 'towers', pos, 40)
    if self.acuFleeing then
        if f > 0.7 or (danger <= 0 and Dist(pos, self.home) < 30) then
            self.acuFleeing = false
        elseif Dist(pos, self.home) > 20 and Commander.Cooldown(self, 'acuflee', 8) then
            Order({ acu }, 'move', self.home)
        end
        return
    end
    if (f < 0.4 and danger > 3) or (f < 0.6 and danger > Power(acu) * 1.5) then
        self.acuFleeing = true
        self.plan = 'comandante recuando'
        Order({ acu }, 'move', self.home)
        return
    end
    -- early on, a healthy ACU helps defend the base when the army is not enough
    if threatPos and Now() < 600 and f > 0.7 and Dist(threatPos, self.home) < 80
        and PowerOf(self.squads.main.members) < threatPower and Dist(pos, self.home) < 80 then
        if not self.acuDefending or Commander.Cooldown(self, 'acudef', 15) then
            self.acuDefending = true
            Order({ acu }, 'attack', threatPos)
        end
    elseif self.acuDefending then
        self.acuDefending = false
        Order({ acu }, 'move', self.home)
    end
end

-- ---------------------------------------------------------------- the Alsyper Adapter
-- The center of the AI. A set of "genes" (how aggressive, how patient, how much it expands,
-- defends, scouts, raids, goes for tech, uses the air force and the navy) moves the whole
-- commander. They start from what the earlier matches taught (per map and in general, with a
-- small mutation every match: the AI evolves), and keep moving during the match with what it
-- sees: how its attacks end, what kills its units, the human's style, the map, its economy
-- against the enemy's and the districts it loses. Every change is written in the journal with
-- its reason.
local GENES = { 'aggression', 'patience', 'expansion', 'defense', 'scouting', 'harass', 'tech', 'air', 'naval' }
local GENE_LABEL = {
    aggression = 'agressao', patience = 'paciencia', expansion = 'expansao', defense = 'defesa', scouting = 'reconhecimento',
    harass = 'saques', tech = 'tecnologia', air = 'aviacao', naval = 'marinha',
}

local function ClampGene(v)
    if v < 0.3 then return 0.3 end
    if v > 1.8 then return 1.8 end
    return v
end

-- genes at the start of the match: the launcher's sliders, the personality, what earlier
-- matches taught, then a small mutation
function Commander.InitGenes(self)
    local g = {}
    for _, k in ipairs(GENES) do g[k] = 1 end
    local P = self.P
    g.aggression = 1 + (1.35 - (P.ratio or 1.35)) * 1.5
    g.patience = P.size or 1
    g.defense = P.towers or 1
    g.harass = (P.raid or 5) / 5
    g.air = P.air or 1
    g.naval = (P.fleet and 1.3) or 1
    g.tech = P.tech or 1
    g.expansion = P.expand or 1
    local prior = CPAI.genesPrior
    local learned = 0
    if type(prior) == 'table' then
        for _, k in ipairs(GENES) do
            if type(prior[k]) == 'number' then
                g[k] = g[k] * 0.4 + prior[k] * 0.6
                learned = learned + 1
            end
        end
    end
    -- the player's sliders in the launcher
    g.aggression = g.aggression * CFG.aggression
    g.expansion = g.expansion * CFG.districts
    g.air = g.air * CFG.airbias
    g.naval = g.naval * CFG.navalbias
    -- mutation: every match tries something a little different (kept when it works)
    for _, k in ipairs(GENES) do
        local r = (Rand(0, 1000) / 1000 - 0.5) * 0.16
        g[k] = ClampGene(g[k] * (1 + r))
    end
    self.genes = g
    self.generation = (CPAI.generation or 0) + 1
    self.adapterLog = learned > 0 and 'comecou do que aprendeu nas partidas anteriores' or 'primeira partida: comecou do zero'
    Commander.Note(self, 'Alsyper geracao ' .. self.generation .. ': ' .. self.adapterLog)
end

function Commander.Gene(self, k)
    return self.genes and self.genes[k] or 1
end

-- moves a gene and writes why
function Commander.Shift(self, k, amount, why)
    if not self.genes then return end
    local old = self.genes[k]
    self.genes[k] = ClampGene(old + amount)
    if math.abs(self.genes[k] - old) >= 0.01 and why then
        local dir = amount > 0 and 'mais ' or 'menos '
        Commander.Note(self, 'Alsyper: ' .. dir .. GENE_LABEL[k] .. ' (' .. why .. ')')
        self.adapterLog = dir .. GENE_LABEL[k] .. ': ' .. why
    end
end

-- how much of the map is water (sampled once)
local function WaterShare()
    if CPAI.waterShare then return CPAI.waterShare end
    local W, H = MapSize()
    local n, wet = 0, 0
    for i = 1, 12 do
        for j = 1, 12 do
            n = n + 1
            if IsWater(W * (i - 0.5) / 12, H * (j - 0.5) / 12) then wet = wet + 1 end
        end
    end
    CPAI.waterShare = wet / math.max(1, n)
    return CPAI.waterShare
end

function Commander.Adapter(self)
    if not self.genes then Commander.InitGenes(self) end
    if not Commander.Cooldown(self, 'alsyper', 20) then return end
    local T, last = self.tally, self.lastTally or {}
    local won = T.won - (last.won or 0)
    local lost = T.retreats - (last.retreats or 0)
    local fell = T.lost - (last.lost or 0)
    self.lastTally = { won = T.won, retreats = T.retreats, lost = T.lost }
    -- 1. how its attacks end
    if lost > won then
        Commander.Shift(self, 'aggression', -0.06, 'os ataques estao falhando')
        Commander.Shift(self, 'patience', 0.06, 'juntar mais tropas antes de atacar')
    elseif won > 0 and lost == 0 then
        Commander.Shift(self, 'aggression', 0.05, 'os ataques estao dando certo')
        Commander.Shift(self, 'patience', -0.04, nil)
    end
    -- 2. what kills its units
    local lb = self.lossBy
    if lb.air >= 5 and lb.air > lb.land then Commander.Shift(self, 'air', 0.06, 'perdendo unidades para a aviacao') end
    if lb.towers >= 5 and lb.towers > lb.land then Commander.Shift(self, 'tech', 0.04, 'torres demais: artilharia e pesquisa') end
    -- 3. districts that fall
    if fell > 0 then Commander.Shift(self, 'defense', 0.08 * fell, 'perdeu bairros') end
    -- 4. the human's style (only what it has seen with its own scouts)
    local M = Commander.M(self)
    if M and self.seenAt then
        local st = M.style
        if (st.rush or 0) > 0.5 then Commander.Shift(self, 'defense', 0.04, 'voce ataca cedo') end
        if (st.turtle or 0) > 0.5 then Commander.Shift(self, 'tech', 0.04, 'voce se fecha em torres') Commander.Shift(self, 'expansion', 0.03, nil) end
        if (st.air or 0) > 0.4 then Commander.Shift(self, 'air', 0.05, 'voce usa muita aviacao') end
        if (st.naval or 0) > 0.4 then Commander.Shift(self, 'naval', 0.05, 'voce usa o mar') end
        if (st.eco or 0) > 0.5 then Commander.Shift(self, 'harass', 0.05, 'voce expande muito: saquear') end
        if (st.tech or 0) > 0.4 then Commander.Shift(self, 'aggression', 0.03, 'voce vai para experimentais: atacar antes') end
        if (st.raider or 0) > 0.5 then Commander.Shift(self, 'defense', 0.03, 'voce saqueia os extratores') end
    end
    -- 5. the map
    if not self.mapRead then
        self.mapRead = true
        local w = WaterShare()
        if w > 0.35 then Commander.Shift(self, 'naval', 0.2, 'mapa com muita agua') Commander.Shift(self, 'air', 0.1, nil) end
        if w < 0.05 then Commander.Shift(self, 'naval', -0.3, 'mapa sem mar') end
        local W, H = MapSize()
        if math.min(W, H) >= 1500 then Commander.Shift(self, 'expansion', 0.15, 'mapa grande') end
    end
    -- 6. economy against the enemy's
    local S = Snapshot()
    local theirs, n = 0, 0
    for _, idx in ipairs(self.enemies) do
        if S.armies[idx] then theirs = theirs + S.armies[idx].extractors n = n + 1 end
    end
    if n > 0 and (self.extractors or 0) + 3 < theirs / n then Commander.Shift(self, 'expansion', 0.04, 'economia menor que a sua') end
    -- 7. a long quiet game: the human is probably growing; go and look
    if Now() - (self.seenAt or 0) > 240 then Commander.Shift(self, 'scouting', 0.05, 'faz tempo que nao ve voce') end
end

-- ---------------------------------------------------------------- early scouting and belief
-- The AI acts like a player that cannot see the whole map: what it believes about each enemy
-- (army, air force, towers, factories, experimentals) only changes when one of its units sees
-- it. At the start it sends a fast plane (or a land scout) to each enemy base, and again every
-- few minutes; without vision it says so in the journal.
function Commander.Believe(self)
    local S = Snapshot()
    local mine = S.armies[self.army]
    if not mine then return end
    local eyes = {}
    for _, m in ipairs(mine.mobile) do table.insert(eyes, m.pos) end
    for _, st in ipairs(mine.structs) do
        table.insert(eyes, st.pos)
    end
    self.belief = self.belief or {}
    local t = Now()
    for _, idx in ipairs(self.enemies) do
        local A = S.armies[idx]
        if A then
            local seen = { air = 0, land = 0, naval = 0, towers = 0, factories = 0, exp = 0, expfactory = false, at = t, home = false }
            local any = false
            local function visible(p, r)
                for _, e in ipairs(eyes) do if Dist(e, p) < r then return true end end
                return false
            end
            for _, m in ipairs(A.mobile) do
                if not m.engineer and visible(m.pos, 70) then
                    any = true
                    if m.air then seen.air = seen.air + m.p + m.ap * 0.5 + 1
                    elseif m.naval then seen.naval = seen.naval + m.p
                    else seen.land = seen.land + m.p end
                    if m.exp then seen.exp = seen.exp + 1 end
                end
            end
            for _, st in ipairs(A.structs) do
                if visible(st.pos, 80) then
                    any = true
                    if st.kind == 'factory' then seen.factories = seen.factories + 1 end
                    if st.kind == 'expfactory' then seen.expfactory = st.pos end
                    seen.towers = seen.towers + st.defense
                end
            end
            local ok, x, z = pcall(A.brain.GetArmyStartPos, A.brain)
            if ok and x and visible(Point(x, z), 90) then seen.home = true end
            if any then
                local old = self.belief[idx]
                -- what was seen now, merged with what it knew (units out of sight are still there)
                if old then
                    for _, k in { 'air', 'land', 'naval', 'towers', 'factories', 'exp' } do seen[k] = math.max(seen[k], old[k] * 0.85) end
                    seen.expfactory = seen.expfactory or old.expfactory
                    seen.home = seen.home or old.home
                end
                if seen.home and not (old and old.home) then
                    Commander.Note(self, 'batedor viu a base inimiga: ' .. seen.factories .. ' fabrica(s), forca ' .. math.floor(seen.land + seen.air))
                end
                self.belief[idx] = seen
                if seen.home then self.seenAt = t end
            end
        end
    end
end

-- what the AI believes the enemies have (sum)
function Commander.Believed(self)
    local out = { air = 0, land = 0, naval = 0, towers = 0, factories = 0, exp = 0, expfactory = false }
    for _, b in (self.belief or {}) do
        for _, k in { 'air', 'land', 'naval', 'towers', 'factories', 'exp' } do out[k] = out[k] + b[k] end
        out.expfactory = out.expfactory or b.expfactory
    end
    return out
end

function Commander.EarlyScout(self)
    local t = Now()
    local every = 240 / Commander.Gene(self, 'scouting')
    if t < 40 then return end
    local due = not self.seenAt or t - self.seenAt > every
    if not due then return end
    if not self.firstScoutNote then
        self.firstScoutNote = true
        Commander.Note(self, 'nao ve o mapa inteiro: mandando batedores para ver o seu progresso')
    end
    local scout = self.squads.scouts.members[1] or self.squads.fighters.members[1] or self.squads.raid.members[1]
    if not scout then
        if Commander.Cooldown(self, 'scoutplane', 60) then
            if not (Commander.Queue(self, self.units.fighter, 1)) then Commander.Queue(self, self.units.tank, 1) end
        end
        return
    end
    if not Commander.Cooldown(self, 'earlyscout', 30) then return end
    -- every enemy base, one after the other, then home
    local homes = Commander.EnemyHomes(self)
    if table.getn(homes) == 0 then return end
    self.scoutTurn = math.mod(self.scoutTurn or 0, table.getn(homes)) + 1
    local goal = homes[self.scoutTurn]
    pcall(IssueClearCommands, { scout })
    Order({ scout }, 'move', goal)
    Order({ scout }, 'move', self.home, true)
    self.plan = 'reconhecendo a base inimiga'
end

-- ---------------------------------------------------------------- research, the ACU and tech
local RESEARCH = {
    -- [personality or plan] = { UEF, Cybran, Illuminate }
    land = { { 'ULB_DAMAGE', 'ULB_HEALTH', 'ULB_RANGE' }, { 'CLB_RATEOFFIRE', 'CLB_HYPERALLOYS', 'CLB_MOVESPEED' }, { 'ILB_DAMAGE', 'ILB_CHROMEHEALTH', 'ILB_RANGE' } },
    air = { { 'UAB_HEALTH', 'UAU_GUNSHIP', 'UAP_CLUSTERBOMBS' }, { 'CAB_DAMAGE', 'CAU_GUNSHIP', 'CAB_HEALTH' }, { 'IAB_DAMAGE', 'IAU_GUNSHIP', 'IAB_HEALTH' } },
    defense = { { 'UBB_INCREASEHEALTH', 'UBP_PDUPGRADE', 'UBU_SHIELDGENERATOR' }, { 'CBB_HEALTH', 'CBB_RATEOFFIRE', 'CBU_SHIELDGENERATOR' }, { 'IBB_DAMAGE', 'IBU_SHIELDGENERATOR', 'IBP_SHIELDENERGYSPONGE' } },
    eco = { { 'UBB_MASSINCOME', 'UBB_ENERGYINCOME', 'UBB_BUILDTIME' }, { 'CBB_BUILDCOST', 'CBB_BUILDTIME', 'CBU_MASSCONVERTOR' }, { 'IBB_MASSINCOME', 'IBB_ENERGYINCOME', 'IBB_RESEARCHRATE' } },
    tech = { { 'ULU_FATBOY', 'ULU_KINGKRIPTOR', 'UAU_AIRFORTRESS' }, { 'CLU_MEGALITHII', 'CAU_SOULRIPPERII', 'CLU_CREX' }, { 'ILU_UNIVERSALCOLOSSUS', 'IAU_CZAR', 'ILU_URCHINOW' } },
    acuDefense = { { 'UCB_HEALTH', 'UCB_REGENERATION', 'UCA_HUNKER' }, { 'CCB_HEALTH', 'CCA_HUNKER', 'CCB_MOVESPEED' }, { 'ICB_MOVESPEED', 'ICA_HUNKER', 'ICA_TELEPORT' } },
    acuAttack = { { 'UCB_DAMAGE', 'UCB_RANGE', 'UCP_AA' }, { 'CCB_RATEOFFIRE', 'CCP_NANOBOTWEAPON', 'CCP_AA' }, { 'ICB_DAMAGE', 'ICB_RANGE', 'ICP_AA' } },
}
local PLAN_OF = { balanced = 'land', aggressive = 'land', defensive = 'defense', raider = 'land', naval = 'eco', airborne = 'air',
    engineer = 'defense', blitz = 'land', titan = 'tech' }

-- puts research at the front of the game's own list (it researches what it needs first)
function Commander.Want(self, names, why)
    local sys = self.brain.SkirmishAISystem
    if not sys or type(sys.ResearchNeeds) ~= 'table' then return false end
    local added = false
    for i = table.getn(names), 1, -1 do
        local n = names[i]
        if n and not self.needs[n] then
            self.needs[n] = true
            table.insert(sys.ResearchNeeds, 1, n)
            added = true
        end
    end
    if added and why then Commander.Note(self, 'pesquisa: ' .. why) end
    return added
end

function Commander.ResearchPlan(self)
    local t = Now()
    if t < 30 or not Commander.Cooldown(self, 'researchplan', 60) then return end
    local f = self.faction
    if not self.planned then
        self.planned = true
        local plan = PLAN_OF[self.personalityKey] or 'land'
        if Commander.Gene(self, 'air') > 1.3 then plan = 'air' end
        if Commander.Gene(self, 'tech') > 1.35 then plan = 'tech' end
        Commander.Want(self, RESEARCH[plan][f], 'plano de ' .. plan)
        if Commander.Gene(self, 'expansion') > 1.1 then Commander.Want(self, RESEARCH.eco[f], nil) end
    end
    -- the ACU: armor while it is being hit, weapons while it fights forward
    if self.acuFleeing or (self.threatPos and Dist(self.threatPos, self.home) < 80) then
        Commander.Want(self, RESEARCH.acuDefense[f], 'blindagem do comandante')
    elseif self.acuDefending or (self.squads.main.state == 'attack' and t > 600) then
        Commander.Want(self, RESEARCH.acuAttack[f], 'armas do comandante')
    end
    if Commander.Gene(self, 'defense') > 1.3 then Commander.Want(self, RESEARCH.defense[f], 'defesas mais fortes') end
    if t > 900 and Commander.Gene(self, 'tech') > 1.05 then Commander.Want(self, RESEARCH.tech[f], 'experimentais') end
end

-- the experimental race: the enemy is building one (seen by the scouts) -> strike the factory
-- when strong enough, otherwise rush the forge
function Commander.ExperimentalRace(self)
    local b = Commander.Believed(self)
    if not b.expfactory or not Commander.Cooldown(self, 'exprace', 60) then return end
    local mine = PowerOf(self.squads.main.members)
    local there = Commander.Danger(self, b.expfactory, 45)
    if mine >= there * self.ratio then
        self.expStrike = b.expfactory
        Commander.Note(self, 'viu a sua fabrica de experimental: vai destrui-la antes de ficar pronta')
    else
        self.expStrike = false
        self.forgeNow = true
        Commander.Want(self, RESEARCH.tech[self.faction], nil)
        Commander.Note(self, 'viu a sua fabrica de experimental: correndo para fazer o dela primeiro')
    end
end

-- nukes once it is ahead late in the game; anti-nukes when the human has a launcher
local NUKE = { 'uub0107', 'ucb0204', 'uib0107' }
local ANTINUKE = { 'uub0203', 'ucb0204', 'uib0203' }
function Commander.Nukes(self)
    if not CFG.build or not Commander.Cooldown(self, 'nukes', 20) then return end
    local t = Now()
    local M = Commander.M(self)
    if M and M.nukes and not self.antiNuke then
        self.antiNuke = true
        pcall(self.brain.SkirmishAISystem.ResearchNeed, self.brain.SkirmishAISystem, 'NeedAntiNukes')
        Commander.Note(self, 'voce tem missil nuclear: defesa antimissil')
    end
    if self.antiNuke and Stored(self.brain, 'MASS') > 400 and not self.antiNukeBuilt then
        if Commander.Build(self, ANTINUKE[self.faction], Toward(self.home, Commander.NearestEnemyStart(self) or self.home, -10)) then self.antiNukeBuilt = true end
    end
    if t < 1200 or self.adaptive > 0 or Commander.Gene(self, 'tech') < 0.9 then return end
    if not self.nukeWanted then
        self.nukeWanted = true
        pcall(self.brain.SkirmishAISystem.ResearchNeed, self.brain.SkirmishAISystem, 'NeedNukes')
        Commander.Note(self, 'pesquisando missil nuclear')
    end
    local forge = false
    for _, d in (self.districts or {}) do if d.role == 'forge' or d.role == 'rear' then forge = d break end end
    local silos = Commander.List(self, Cat('NUKE STRUCTURE'))
    if table.getn(silos) == 0 then
        if Stored(self.brain, 'MASS') > 600 then Commander.Build(self, NUKE[self.faction], (forge and forge.pos) or self.home) end
        return
    end
    -- launch at the most valuable enemy place
    local best, bestV = false, 0
    for _, cell in Commander.Targets(self) do
        if cell.value > bestV then best, bestV = cell.pos, cell.value end
    end
    if not best then return end
    for _, s in ipairs(silos) do
        pcall(IssueSiloBuildNuke, { s })
        local ok, ammo = pcall(s.GetNukeSiloAmmoCount, s)
        if ok and ammo and ammo > 0 and pcall(IssueNuke, { s }, best) then
            Commander.Note(self, 'lancou um missil nuclear')
            return
        end
    end
end

-- mass converters when energy piles up and mass is short
function Commander.Converters(self)
    if not CFG.build or Now() < 600 or not Commander.Cooldown(self, 'converter', 90) then return end
    if Stored(self.brain, 'ENERGY') < 2000 or Stored(self.brain, 'MASS') > 150 then return end
    pcall(self.brain.SkirmishAISystem.ResearchNeed, self.brain.SkirmishAISystem, 'NeedMassConv')
    local ids = { 'uub0704', 'ucb0704', 'uib0704' }
    local spot = self.home
    for _, d in (self.districts or {}) do if d.role == 'rear' then spot = d.pos break end end
    if Commander.Build(self, ids[self.faction], spot) then Commander.Note(self, 'energia sobrando: conversor de massa') end
end

-- ---------------------------------------------------------------- timing, ambush and decoys
-- the right moment: the enemy army just lost a lot, or walked far from home
function Commander.Timing(self)
    local S = Snapshot()
    local t = Now()
    local power, far = 0, false
    for _, idx in ipairs(self.enemies) do
        local A = S.armies[idx]
        if A then
            power = power + A.power
            local ok, x, z = pcall(A.brain.GetArmyStartPos, A.brain)
            local c = Centroid((function() local l = {} for _, m in ipairs(A.mobile) do if not m.air and not m.engineer and m.u then table.insert(l, m.u) end end return l end)())
            if ok and x and c and Dist(c, Point(x, z)) > Dist(Point(x, z), self.home) * 0.6 then far = true end
        end
    end
    local hist = self.powerHist or {}
    table.insert(hist, { t = t, p = power })
    while hist[1] and t - hist[1].t > 40 do table.remove(hist, 1) end
    self.powerHist = hist
    local peak = 0
    for _, h in ipairs(hist) do peak = math.max(peak, h.p) end
    local reason = false
    if peak > 10 and power < peak * 0.6 then reason = 'o seu exercito acabou de perder uma luta' end
    if far and power > 0 then reason = reason or 'o seu exercito esta longe de casa' end
    if reason and (not self.window or t > self.window) then
        self.window = t + 30
        self.windowWhy = reason
        Commander.Note(self, 'hora certa de atacar: ' .. reason)
    end
end

function Commander.InWindow(self)
    return self.window and Now() < self.window
end

-- a few units hide beside the route the human uses (out of sight) and jump on the passing army
function Commander.Ambush(self)
    local M = Commander.M(self)
    local sq = self.squads.ambush
    if not sq then return end
    local members = sq.members
    local main = self.squads.main
    local spot = M and Hottest(M.route, self.home, 80, 400, 2)
    if not spot then
        for _, u in ipairs(sq.units) do u.CPSquad = 'main' end
        return
    end
    -- take a few units from the army while it waits
    if table.getn(members) < 4 and main.state == 'hold' and table.getn(main.members) > Commander.MinUnits(self) then
        for i = table.getn(main.members), 1, -1 do
            local u = main.members[i]
            if table.getn(sq.units) >= 4 then break end
            if not Is(Categories().experimental, u) then
                u.CPSquad = 'ambush'
                table.insert(sq.units, u)
                table.remove(main.members, i)
            end
        end
        members = sq.units
    end
    if table.getn(members) == 0 then return end
    local enemy = Commander.NearestEnemyStart(self) or self.home
    local d = math.max(1, Dist(spot, enemy))
    local hide = Point(spot[1] - (enemy[3] - spot[3]) / d * 45, spot[3] + (enemy[1] - spot[1]) / d * 45)
    if IsWater(hide[1], hide[3]) then hide = Point(spot[1] + (enemy[3] - spot[3]) / d * 45, spot[3] - (enemy[1] - spot[1]) / d * 45) end
    local passing = Commander.MobileDanger(self, spot, 50)
    if passing >= 3 and passing <= PowerOf(members) * 2.5 then
        if sq.state ~= 'attack' then
            sq.state = 'attack'
            Commander.Command(self, sq, members, 'attack', spot)
            Commander.Note(self, 'emboscada: atacou o seu exercito no caminho')
        end
    elseif sq.state ~= 'hide' or not sq.post or Dist(sq.post, hide) > 20 then
        sq.state = 'hide'
        sq.post = hide
        Commander.Command(self, sq, members, 'move', hide)
    end
end

-- before a hard attack, the raiders strike somewhere else first so the defense goes there
function Commander.Decoy(self, squad, target)
    local raid = self.squads.raid
    if squad.name ~= 'main' or table.getn(raid.members) < 2 or not Commander.Cooldown(self, 'decoy', 120) then return false end
    if Commander.Danger(self, target, 45) < 6 then return false end
    local far, farD = false, 0
    for _, cell in Commander.Targets(self) do
        local d = Dist(cell.pos, target)
        if d > 180 and d > farD and Commander.CanReach(self, raid.members, cell.pos, 'land') then far, farD = cell.pos, d end
    end
    if not far then return false end
    raid.state = 'attack'
    raid.target = far
    raid.attackSince = Now()
    Commander.Command(self, raid, raid.members, 'attack', far)
    squad.state = 'gather'
    squad.gatherUntil = Now() + 12
    squad.rally = squad.center
    Commander.Note(self, 'isca: os rapidos atacaram longe antes do ataque principal')
    return true
end

-- ---------------------------------------------------------------- economy taken from the enemy
-- extractors destroyed by the army become ours; wreckage after a big fight is reclaimed
local EXTRACTOR = { 'uub0701', 'ucb0701', 'uib0701' }
function Commander.Steal(self)
    if not CFG.build or not self.stealSpots or table.getn(self.stealSpots) == 0 then return end
    if not Commander.Cooldown(self, 'steal', 20) then return end
    local spot = self.stealSpots[1]
    if Commander.MobileDanger(self, spot, 60) >= 3 then return end
    local S = Snapshot()
    -- someone already built there
    for _, A in S.armies do
        for _, st in ipairs(A.structs) do
            if st.kind == 'extractor' and Dist(st.pos, spot) < 4 then table.remove(self.stealSpots, 1) return end
        end
    end
    local builders = {}
    for _, e in ipairs(Commander.List(self, Categories().engineer)) do
        if e.CPBuilder and not e.CPIsland and Ready(e) then table.insert(builders, e) end
    end
    local eng = builders[1] or Commander.Engineer(self, spot, false)
    if not eng then return end
    pcall(IssueClearCommands, { eng })
    if pcall(self.brain.BuildStructure, self.brain, eng, EXTRACTOR[self.faction], { spot[1], spot[3], 0 }, false) then
        table.remove(self.stealSpots, 1)
        Commander.Note(self, 'pegou um extrator seu que foi destruido')
    end
end

function Commander.Reclaim(self, pos)
    if not pos or not Commander.Cooldown(self, 'reclaim', 45) then return end
    local ok, list = pcall(function() return GetReclaimablesInRect(Rect(pos[1] - 40, pos[3] - 40, pos[1] + 40, pos[3] + 40)) end)
    if not ok or type(list) ~= 'table' then return end
    local eng = Commander.Engineer(self, pos, false)
    if not eng then return end
    local n = 0
    for _, w in list do
        if n >= 6 then break end
        if pcall(IssueReclaim, { eng }, w) then n = n + 1 end
    end
    if n > 0 then Commander.Note(self, 'recolhendo destrocos depois da luta') end
end

-- ---------------------------------------------------------------- the air force patrols
function Commander.AirPatrol(self, fighters)
    if table.getn(fighters) == 0 or not Commander.Cooldown(self, 'patrol', 40) then return end
    local route = { self.home }
    for _, d in (self.districts or {}) do
        if d.step > 2 and table.getn(route) < 5 then table.insert(route, d.pos) end
    end
    if table.getn(route) < 2 then return end
    pcall(IssueClearCommands, fighters)
    for _, p in ipairs(route) do pcall(IssuePatrol, fighters, p) end
    self.squads.fighters.state = 'patrol'
end

-- ---------------------------------------------------------------- tips and talk for the panel
-- training: what this AI is about to do to you (only the human's enemies, only once per plan)
function Commander.Tip(self)
    if not CFG.tips or not self.facesHuman then return false end
    local main = self.squads.main
    if main.state ~= 'attack' or not main.target or not main.center then return false end
    local speed = 3
    local eta = math.floor(Dist(main.center, main.target) / speed)
    if eta < 5 then return false end
    local W, H = MapSize()
    return { pos = main.target, at = { main.target[1] / W, main.target[3] / H }, eta = eta, n = table.getn(main.members) }
end

function Commander.Say(self, text)
    if not CFG.chat or not self.facesHuman then return end
    self.sayN = (self.sayN or 0) + 1
    self.said = { n = self.sayN, text = text }
end

-- ---------------------------------------------------------------- strategies (doctrines)
-- The Alsyper Adapter keeps two strategies at a time (a main one and a support one), chosen by
-- what it knows: the map, the human's style, its genes, the economy and how the match is going.
-- Each strategy nudges the genes and turns on behaviours; changes go to the journal with why.
local STRATEGIES = {
    { id = 'fastland', label = 'Expansao terrestre rapida', when = function(c) return Now() < 480 and WaterShare() < 0.3 and 1.2 or 0.2 end, genes = { expansion = 0.25, patience = -0.1 } },
    { id = 'economy', label = 'Dominio economico', when = function(c) return (c.extractors or 0) < c.enemyExtractors and 1.1 or 0.5 end, genes = { expansion = 0.2, harass = -0.1 } },
    { id = 'scouting', label = 'Reconhecimento constante', when = function(c) return (Now() - (c.seenAt or -999)) > 180 and 1.2 or 0.3 end, genes = { scouting = 0.3 } },
    { id = 'combined', label = 'Exercito combinado', when = function(c) return 0.8 end, genes = { patience = 0.05 } },
    { id = 'airsup', label = 'Supremacia aerea', when = function(c) return (c.intel.air or 0) > 10 and 1.3 or Commander.Gene(c, 'air') * 0.6 end, genes = { air = 0.3 } },
    { id = 'turtle', label = 'Defesa fortificada', when = function(c) return (c.adaptive > 0 or c.tally.lost > 1) and 1.3 or Commander.Gene(c, 'defense') * 0.5 end, genes = { defense = 0.3, aggression = -0.1 } },
    { id = 'experimental', label = 'Investimento em experimentais', when = function(c) return Now() > 900 and Commander.Gene(c, 'tech') or 0.1 end, genes = { tech = 0.3 } },
    { id = 'acupush', label = 'Pressao com o comandante', when = function(c) return Now() < 420 and c.personalityKey ~= 'defensive' and 0.9 or 0 end, genes = { aggression = 0.1 } },
    { id = 'naval', label = 'Dominio naval', when = function(c) return WaterShare() > 0.3 and Commander.Gene(c, 'naval') * 1.1 or 0 end, genes = { naval = 0.3 } },
    { id = 'simultaneous', label = 'Ataques simultaneos', when = function(c) return table.getn(c.squads.main.members) >= Commander.MinUnits(c) * 2.5 and 1.2 or 0.2 end, genes = { aggression = 0.1 } },
    { id = 'ecopressure', label = 'Pressao economica', when = function(c) return Commander.Gene(c, 'harass') * 0.8 + ((c.enemyExtractors or 0) > (c.extractors or 0) + 4 and 0.5 or 0) end, genes = { harass = 0.25 } },
    { id = 'focus', label = 'Fogo concentrado', when = function(c) return CFG.micro and 0.6 or 0 end, genes = {} },
    { id = 'veterans', label = 'Veterania das unidades', when = function(c) return Now() > 600 and 0.7 or 0.1 end, genes = { patience = 0.05 } },
    { id = 'rally', label = 'Pontos de reuniao e patrulhas', when = function(c) return 0.5 end, genes = {} },
    { id = 'reclaim', label = 'Recuperacao de destrocos', when = function(c) return Stored(c.brain, 'MASS') < 100 and 0.9 or 0.2 end, genes = {} },
    { id = 'fronts', label = 'Controle de varias frentes', when = function(c) return table.getn(c.districts or {}) >= 4 and 0.9 or 0.2 end, genes = { expansion = 0.05 } },
    { id = 'antinuke', label = 'Defesa antinuclear', when = function(c) local M = Commander.M(c) return M and M.nukes and 2 or 0 end, genes = { defense = 0.1 } },
    { id = 'longarty', label = 'Artilharia de longo alcance', when = function(c) return (c.intel.towers or 0) > 30 and 1.2 or 0.2 end, genes = { tech = 0.1 } },
    { id = 'flanks', label = 'Ataques pelos flancos', when = function(c) return c.P.pincer and 0.7 or 0.2 end, genes = { aggression = 0.05 } },
    { id = 'territory', label = 'Expansao territorial estrategica', when = function(c) return Now() > 300 and Commander.Gene(c, 'expansion') * 0.8 or 0.3 end, genes = { expansion = 0.15 } },
    { id = 'balance', label = 'Equilibrio entre massa e energia', when = function(c) return (Stored(c.brain, 'ENERGY') < 200 or Stored(c.brain, 'ENERGY') > 3000) and 1.1 or 0.3 end, genes = {} },
    { id = 'research', label = 'Pesquisa tecnologica antecipada', when = function(c) return Now() < 600 and Commander.Gene(c, 'tech') * 0.7 or 0.2 end, genes = { tech = 0.15 } },
    { id = 'engineers', label = 'Protecao de engenheiros', when = function(c) return c.engineerThreat and 1.5 or 0.3 end, genes = { defense = 0.05 } },
    { id = 'counter', label = 'Contra-ataque especializado', when = function(c) return (c.squads.main.counterUntil or 0) > Now() and 1.5 or 0.4 end, genes = {} },
    { id = 'team', label = 'Coordenacao de ataques em equipe', when = function(c) return table.getn(Commander.Allies(c)) > 0 and 1.0 or 0 end, genes = {} },
}

function Commander.Strategy(self, id)
    return self.strategy and (self.strategy[1] == id or self.strategy[2] == id)
end

function Commander.ChooseStrategy(self)
    if not self.genes or not Commander.Cooldown(self, 'strategy', 90) then return end
    local S = Snapshot()
    local theirs, n = 0, 0
    for _, idx in ipairs(self.enemies) do
        if S.armies[idx] then theirs = theirs + S.armies[idx].extractors n = n + 1 end
    end
    self.enemyExtractors = n > 0 and theirs / n or 0
    local scored = {}
    for _, st in ipairs(STRATEGIES) do
        local ok, v = pcall(st.when, self)
        if ok and type(v) == 'number' and v > 0 then table.insert(scored, { st = st, v = v }) end
    end
    table.sort(scored, function(a, b) return a.v > b.v end)
    local first, second = scored[1] and scored[1].st, scored[2] and scored[2].st
    if not first then return end
    local old = self.strategy
    self.strategy = { first.id, second and second.id or first.id }
    self.strategyLabel = first.label .. (second and (' + ' .. second.label) or '')
    if not old or old[1] ~= first.id or old[2] ~= self.strategy[2] then
        for _, st in { first, second } do
            if st then for k, v in st.genes do Commander.Shift(self, k, v * 0.3, nil) end end
        end
        Commander.Note(self, 'estrategia: ' .. self.strategyLabel)
    end
end

-- veterans and units of great value are pulled back earlier (they are worth more alive)
function CPVeteran(u)
    local ok, lvl = pcall(function() return u:GetVeteranLevel() end)
    if ok and type(lvl) == 'number' then return lvl end
    return u.VeteranLevel or 0
end

-- engineers building far from home flee from enemies, and a few units come to guard them
function Commander.ProtectEngineers(self)
    self.engineerThreat = false
    local guard = {}
    for _, e in ipairs(Commander.List(self, Categories().engineer)) do
        if e.CPBuilder and Ready(e) then
            local pos = e:GetPosition()
            local danger = Commander.MobileDanger(self, pos, 45)
            if danger >= 2 then
                self.engineerThreat = pos
                if not e.CPFleeing then
                    e.CPFleeing = true
                    pcall(IssueClearCommands, { e })
                    Order({ e }, 'move', Commander.SafeSpot(self, pos))
                    Commander.Note(self, 'engenheiro fugindo de inimigos')
                end
                table.insert(guard, pos)
            elseif e.CPFleeing and danger <= 0 then
                e.CPFleeing = nil
            end
        end
    end
    local pos = guard[1]
    if not pos or not Commander.Strategy(self, 'engineers') and self.difficulty < 3 then return end
    local main = self.squads.main
    if main.state ~= 'hold' or table.getn(main.members) < 4 or not Commander.Cooldown(self, 'engguard', 30) then return end
    local n = 0
    local helpers = {}
    for _, u in ipairs(main.members) do
        if n >= 3 then break end
        table.insert(helpers, u)
        n = n + 1
    end
    Order(helpers, 'attack', pos)
end

-- the ACU walks with the army early on (pressure), when healthy and the army is attacking
function Commander.AcuPush(self)
    if not Commander.Strategy(self, 'acupush') or Now() > 480 then return false end
    local acu = Commander.List(self, Categories().acu)[1]
    local main = self.squads.main
    if not acu or not Ready(acu) or self.acuFleeing or HealthFraction(acu) < 0.75 then return false end
    if main.state == 'attack' and main.target and Commander.Cooldown(self, 'acupush', 20) then
        Order({ acu }, 'attack', main.target)
        self.acuPushing = true
        Commander.Note(self, 'comandante avancando junto com o exercito')
        return true
    end
    return false
end

-- the genes of every AI commander in the match, averaged (what goes to memory)
CPAI.GenesAverage = function()
    local sum, n = {}, 0
    for _, cmd in CPAI.commanders do
        if cmd.genes and cmd.facesHuman then
            n = n + 1
            for _, k in ipairs(GENES) do sum[k] = (sum[k] or 0) + cmd.genes[k] end
        end
    end
    if n == 0 then return nil end
    for k, v in sum do sum[k] = math.floor(v / n * 100 + 0.5) / 100 end
    return sum
end

-- ---------------------------------------------------------------- adaptive difficulty
function Commander.Adapt(self)
    if not CFG.adaptive or not Commander.Cooldown(self, 'adapt', 30) then return end
    local S = Snapshot()
    local human, ai = 0, 0
    for idx, A in S.armies do
        if not Civilian(idx) then
            local p = A.power + A.airPower * 0.5
            if A.human then
                if Enemy(self.army, idx) then human = human + p end
            elseif idx == self.army or (CFG.team and Allied(self.army, idx)) then
                ai = ai + p
            end
        end
    end
    local old = self.adaptive
    if human > 30 and human > ai * 1.6 then
        self.adaptive = 1
        -- a small boost while the human is far ahead
        pcall(self.brain.GiveResource, self.brain, 'MASS', 40 * CFG.level)
        pcall(self.brain.GiveResource, self.brain, 'ENERGY', 200 * CFG.level)
    elseif ai > 30 and ai > human * 2.5 then
        self.adaptive = -1
    else
        self.adaptive = 0
    end
    if old ~= self.adaptive then
        self.ratio = Commander.BaseRatio(self)
        if self.adaptive < 0 then self.ratio = self.ratio + 0.4 end
        if self.adaptive > 0 then self.ratio = math.max(1.05, self.ratio - 0.15) end
    end
end

-- ---------------------------------------------------------------- status for the in-game panel
local STATE_LABEL = {
    hold = 'na emboscada', gather = 'juntando tropas', attack = 'atacando', retreat = 'recuando',
    defend = 'defendendo', home = 'voltando para a base', cover = 'cobrindo o exercito', post = 'de guarda',
}

-- districts for the panel: "3/5 bairros (bastiao norte 4/9)"
function Commander.DistrictSummary(self)
    local done, total, current = 0, 0, false
    for _, d in (self.districts or {}) do
        total = total + 1
        local n = table.getn(PlanOf(d))
        if d.step > n then done = done + 1 elseif not current then current = d.name .. ' ' .. (d.step - 1) .. '/' .. n end
    end
    return { done = done, total = total, current = current or '' }
end

function Commander.AdapterSummary(self)
    if not self.genes then return false end
    local parts = {}
    for _, k in ipairs(GENES) do table.insert(parts, GENE_LABEL[k] .. ' ' .. math.floor(self.genes[k] * 100 + 0.5) .. '%') end
    local seen = 'ainda nao viu a sua base'
    if self.seenAt then seen = 'viu a sua base ha ' .. math.floor(Now() - self.seenAt) .. ' s' end
    return { generation = self.generation, genes = table.concat(parts, '  '), last = self.adapterLog or '', seen = seen, strategy = self.strategyLabel or '',
        window = Commander.InWindow(self) and self.windowWhy or false }
end

function Commander.JournalLines(self, n)
    local out = {}
    for i = 1, math.min(n, table.getn(self.journal)) do
        local e = self.journal[i]
        table.insert(out, e.t .. '  ' .. e.text)
    end
    return out
end

-- what the panel's small map shows (positions in 0..1 of the map)
function Commander.MiniMap(self)
    local W, H = MapSize()
    local function at(p) return p and { math.floor(p[1] / W * 1000) / 1000, math.floor(p[3] / H * 1000) / 1000 } or false end
    local list = {}
    for _, d in (self.districts or {}) do
        local q = at(d.pos)
        table.insert(list, { q[1], q[2], d.role, d.step > table.getn(PlanOf(d)) })
    end
    local main = self.squads.main
    return {
        army = self.army, home = at(self.home), districts = list,
        target = main.state == 'attack' and at(main.target) or false, second = main.state == 'attack' and at(main.second) or false,
        predicted = self.predicted and Now() - self.predicted.at < 45 and at(self.predicted.pos) or false,
        join = at(self.joinPos),
    }
end

function Commander.Publish(self)
    if not CFG.status or Humans() ~= 1 then return end
    local function squad(name)
        local sq = self.squads[name]
        return {
            n = table.getn(sq.members),
            power = math.floor(PowerOf(sq.members) + AirPowerOf(sq.members) + 0.5),
            state = STATE_LABEL[sq.state] or sq.state,
        }
    end
    local adaptive = 'normal'
    if self.adaptive > 0 then adaptive = 'pressionando' elseif self.adaptive < 0 then adaptive = 'segurando' end
    local dangers = 0
    for _, w in self.kills do if w >= 2 then dangers = dangers + 1 end end
    local entry = {
        name = self.brain.Nickname or ('IA ' .. self.army),
        personality = self.P.label,
        plan = self.plan,
        adaptive = adaptive,
        main = squad('main'), raid = squad('raid'), fleet = squad('fleet'), drop = squad('drop'),
        fighters = squad('fighters'), bombers = squad('bombers'), gunships = squad('gunships'), guard = squad('guard'),
        minUnits = Commander.MinUnits(self),
        acu = self.acuFleeing and 'recuando' or (self.acuDefending and 'defendendo' or 'na base'),
        intel = { air = math.floor(self.intel.air), land = math.floor(self.intel.land), naval = math.floor(self.intel.naval) },
        dangers = dangers,
        districts = Commander.DistrictSummary(self),
        journal = Commander.JournalLines(self, 5),
        tally = self.tally,
        mini = Commander.MiniMap(self),
        alsyper = Commander.AdapterSummary(self),
        tip = Commander.Tip(self),
        said = self.said,
        time = Now(),
    }
    if Commander.M(self) then entry.learned = CPAIModelSummary() end
    if self.lastError then entry.error = self.lastError end
    CPAI.status[self.army] = entry
end

-- what goes to the interface is kept here and sent again on every tick by SyncThread: the Sync
-- table is emptied after each beat, and the interface may read it on a frame between two beats
local function Report(army, fields)
    local entry = CPAI.status[army]
    if not entry then
        entry = { name = 'IA ' .. army, personality = '-', plan = 'iniciando', adaptive = 'normal', minUnits = 0,
            acu = '-', intel = { air = 0, land = 0, naval = 0 }, dangers = 0 }
        local b = ArmyBrains[army]
        if b and b.Nickname then entry.name = b.Nickname end
        CPAI.status[army] = entry
    end
    for k, v in fields do entry[k] = v end
    entry.time = Now()
end

-- the end of the match against the human: +1 when the human won, -1 when the AIs won
local function MatchResult()
    if CPAI.result then return CPAI.result end
    local human, humanAlive, foes, foesAlive = false, false, 0, 0
    for _, b in ArmyBrains do
        local ok, idx = pcall(b.GetArmyIndex, b)
        if ok and b.BrainType == 'Human' and not Civilian(idx) then
            human = idx
            if not Defeated(b) then humanAlive = true end
        end
    end
    if not human or Now() < 300 then return false end
    for _, b in ArmyBrains do
        local ok, idx = pcall(b.GetArmyIndex, b)
        if ok and b.BrainType ~= 'Human' and not Civilian(idx) and Enemy(human, idx) then
            foes = foes + 1
            if not Defeated(b) then foesAlive = foesAlive + 1 end
        end
    end
    if foes == 0 then return false end
    if not humanAlive then CPAI.result = -1 elseif foesAlive == 0 then CPAI.result = 1 end
    return CPAI.result
end

local function SyncThread()
    while true do
        pcall(function()
            if CFG.status and next(CPAI.status) then Sync.CPAIStatus = CPAI.status end
            if CPAI.modelOut and Now() < (CPAI.modelOutUntil or 0) then Sync.CPAIModel = CPAI.modelOut end
            local r = CFG.learn and MatchResult()
            if r then Sync.CPAIResult = { result = r, genes = CPAI.GenesAverage and CPAI.GenesAverage() or false } end
        end)
        WaitTicks(1)
    end
end

-- the model goes to the interface every 30 s after 5 minutes of play (a match abandoned right at
-- the start does not overwrite what was learned), which keeps it in Game.prefs
function Commander.Remember(self)
    if not CFG.learn or Humans() ~= 1 or Now() < 300 or not Commander.M(self) then return end
    if CPAI.rememberedAt and Now() - CPAI.rememberedAt < 30 then return end
    CPAI.rememberedAt = Now()
    local ok, m = pcall(CPAIModelMemory)
    if ok and m then
        CPAI.modelSeq = (CPAI.modelSeq or 0) + 1
        m.seq = CPAI.modelSeq
        CPAI.modelOut = m
        CPAI.modelOutUntil = Now() + 5
    end
end

-- ---------------------------------------------------------------- main loop
function Commander.Step(self)
    self.memo = {}
    local S = Snapshot()
    self.enemies = EnemyArmies(S, self.army)
    self.facesHuman = false
    for _, idx in ipairs(self.enemies) do
        if S.armies[idx].human then self.facesHuman = true end
    end
    Commander.Recruit(self)
    Commander.Collect(self)
    Commander.AssignGuard(self)
    Commander.Believe(self)
    Commander.Adapter(self)
    Commander.ChooseStrategy(self)
    Commander.Foresee(self)
    Commander.HumanPush(self)
    Commander.Timing(self)
    local clusters = Commander.Clusters(self)
    self.lastClusters = clusters
    local ex = 0
    for _, cl in clusters do ex = ex + cl.extractors end
    self.extractors = ex
    local threatPos, threatPower, threatKey = Commander.Threat(self, clusters)
    self.threatPos, self.threatPower = threatPos, threatPower
    local helpPos, helpPower = false, 0
    if not threatPos then helpPos, helpPower = Commander.AllyThreat(self) end
    for _, name in { 'main', 'raid', 'fleet', 'drop' } do
        local sq = self.squads[name]
        if name == 'main' and not threatPos and helpPos then
            Commander.Lead(self, sq, helpPos, helpPower)
        else
            Commander.Lead(self, sq, threatPos, threatPower)
        end
    end
    local main = self.squads.main
    if threatPos then
        self.plan = 'defendendo'
    elseif main.state == 'attack' then
        self.plan = 'atacando'
    elseif main.state == 'gather' then
        self.plan = 'juntando o exercito'
    elseif self.plan == 'atacando' or self.plan == 'defendendo' or self.plan == 'preparando' then
        self.plan = 'esperando vantagem'
    end
    Commander.LeadGuard(self, threatPos)
    if CFG.air then Commander.LeadAir(self, threatPos) end
    if not Commander.AcuPush(self) then Commander.LeadAcu(self, threatPos, threatPower) end
    Commander.ProtectEngineers(self)
    Commander.EarlyScout(self)
    Commander.Scout(self)
    Commander.Ambush(self)
    Commander.Counter(self)
    Commander.ResearchPlan(self)
    Commander.ExperimentalRace(self)
    Commander.Bases(self, clusters, threatKey)
    Commander.Districts(self, threatPos)
    Commander.BaseShields(self)
    Commander.AirNet(self)
    Commander.Economy(self)
    Commander.Nukes(self)
    Commander.Converters(self)
    Commander.Steal(self)
    Commander.Research(self)
    Commander.Repair(self, threatPos)
    Commander.Adapt(self)
    Commander.Publish(self)
    Commander.Remember(self)
end

-- after repeated errors the units go back to the engine's own AI and the commander stops, so a
-- problem here never leaves the AI worse than the original
function Commander.Release(self)
    local units = {}
    for _, sq in self.squads do
        for _, u in ipairs(sq.units) do
            if Alive(u) then
                u.CPSquad = nil
                u.CPDropping = nil
                table.insert(units, u)
            end
        end
    end
    pcall(function()
        local pool = self.brain:GetPlatoonUniquelyNamed('ArmyPool')
        if pool and table.getn(units) > 0 then self.brain:AssignUnitsToPlatoon(pool, units, 'Unassigned', 'None') end
    end)
    CPAI.commanders[self.army] = nil
    WARN('*CommandProject AI commander: stopped for army ' .. self.army .. ', units returned to the original AI')
    Report(self.army, { plan = 'parou por erro: a IA original do jogo assumiu', stopped = true })
end

function Commander.Run(self)
    local period = 4
    if CFG.level >= 2 then period = 3 end
    if CFG.level >= 3 then period = 2 end
    if self.difficulty <= 1 then period = period + 2 end
    -- many AIs: each one thinks a little less often, and not all on the same tick
    period = period + math.floor(ArmyCount() / 8)
    WaitSeconds(10 + math.mod(self.army, period))
    while not Defeated(self.brain) do
        local ok, err = pcall(Commander.Step, self)
        if ok then
            self.failures = 0
        else
            self.failures = self.failures + 1
            WARN('*CommandProject AI commander: ' .. tostring(err))
            self.lastError = string.sub(tostring(err), 1, 160)
            Report(self.army, { error = self.lastError })
            if self.failures >= 3 then
                Commander.Release(self)
                return
            end
            WaitSeconds(10)
        end
        WaitSeconds(period)
    end
    CPAI.commanders[self.army] = nil
    CPAI.status[self.army] = nil
end

local function ModelThread()
    WaitSeconds(15)
    local failures = 0
    while true do
        local ok, err = pcall(CPAIModelUpdate)
        if ok then
            failures = 0
        else
            failures = failures + 1
            WARN('*CommandProject AI player model: ' .. tostring(err))
            if failures >= 5 then
                CPAI.model = nil
                return
            end
            WaitSeconds(20)
        end
        WaitSeconds(8)
    end
end

-- for tests and debugging: what the main army of an AI is doing
function CPCommanderState(army)
    local c = CPAI.commanders[army]
    return c and c.squads.main.state or false
end

function CPCommanderRun(brain, home)
    if not brain or brain.BrainType == 'Human' then return end
    if not CPAI.modelThread then
        CPAI.modelThread = true
        Model()
        ForkThread(ModelThread)
    end
    if not CPAI.syncThread then
        CPAI.syncThread = true
        ForkThread(SyncThread)
    end
    local ok, self = pcall(Commander.New, brain, home or { 0, 0, 0 })
    if not ok then
        local army = 0
        pcall(function() army = brain:GetArmyIndex() end)
        WARN('*CommandProject AI commander: ' .. tostring(self))
        Report(army, { plan = 'nao iniciou: a IA original do jogo continua', error = string.sub(tostring(self), 1, 160), stopped = true })
        return
    end
    Report(self.army, { name = brain.Nickname or ('IA ' .. self.army), personality = self.P.label, plan = 'preparando' })
    Commander.Run(self)
end
end
